import type { Story } from './history-types';

type Pair = readonly [string, string];
type Entry = { id: string; teaser: Pair; past: Pair; scene: Pair; symbols: readonly (readonly [Pair, Pair])[]; reflection: Pair; detail: Pair };
const historical: Record<string, Pair> = {
  swords: [
    'The Swords suit belongs to the older Italian vocabulary of playing cards. Its history starts with a recognizable object, a weapon, rather than a universal psychological category. A numbered card could identify its value simply by repeating that object; a court card identified a member of an imagined household. Those functions matter because the familiar association of every Sword with a particular emotional experience is a later interpretive layer. The Rider–Waite–Smith deck asks a much more pictorial question: what happens when a blade becomes part of a human situation? Reading its scenes alongside the older suit structure lets us notice both continuity and invention.',
    '宝剑属于意大利纸牌较早的花色语言。它最初是一种人们能够辨认的武器，并非普遍适用的心理学类别。数字牌可以通过重复宝剑来标明点数，宫廷牌则表现想象中宫廷的一位成员。理解这些用途很重要：如今把每张宝剑牌与某种情绪经验联系起来，是后来形成的解释层。韦特—史密斯牌组提出了更具画面感的问题：当利刃进入人的处境，会发生什么？把新场景与旧花色结构对照，才能同时看见传统的延续和创作的变化。',
  ],
  pentacles: [
    'Before this suit was called Pentacles in many English-language decks, it was commonly represented by coins. Its objects belonged to the visible world of payment, possession, and exchange. Waite himself explains that the five-pointed sign adds an esoteric interpretation to an older money emblem, and says that he did not invent that substitution. This is a useful distinction: the suit has a long playing-card ancestry, while the specific star-marked objects and scenes here belong to a particular artistic and interpretive tradition. They invite questions about what people value, make, share, or protect, without establishing an ancient fixed meaning for every number.',
    '在许多英语牌组把这一花色称为 Pentacles 之前，它通常以钱币呈现。钱币属于支付、占有与交换的现实世界。韦特本人解释，五角星符号为旧有钱币图案增加了神秘学层面的理解，并明确表示这种替换不是他的发明。这一区别很重要：花色拥有悠久的纸牌历史，而眼前的星形圆盘与人物场景，属于特定的艺术和解释传统。它们使我们思考人们珍惜、制作、分享或保护什么，却不能证明每个数字自古就有固定的神秘意义。',
  ],
};
// Card-specific comparisons distinguish the 1909 pictures from a dictionary of meanings.
const comparisons: Record<string, Pair> = {
  'swords-01': [
    'Compare this Ace with the King of Swords. Both have a weapon held upright, but only the King occupies a social position and can be asked to account for its use. The Ace removes the institution and keeps the concentrated possibility. Compared with the Three’s pierced heart, it also shows the blade before a consequence has been pictured. These are observations about Smith’s compositions, not a claim that the cards form a compulsory sequence. Together they explain why the Ace can feel exciting and unsettling at once: the tool is unmistakably powerful, but the story of what it will do has not yet been drawn.',
    '可以把它与宝剑国王比较。两张牌的武器都直立，只有国王处于明确社会位置，能够被要求为使用方式负责。王牌移去制度，只留下集中的可能性。与宝剑三被刺穿的心相比，它又呈现了后果尚未被画出之前的利刃。这些是对史密斯构图的观察，并不表示各牌必须构成固定顺序。它们说明王牌为什么既令人兴奋又不安：工具显然强大，它将做什么的故事却还没有被画出来。',
  ],
  'swords-02': [
    'Compare the blindfold here with the one in the Eight of Swords. The Eight’s figure is bound, while the Two’s figure actively holds the weapons. Similar visual details can therefore take part in different situations: restriction in one image, maintained equilibrium in another. The distinction discourages treating every covered eye as a single code for denial. Likewise, the crossed arms are not simply empty passivity; they are doing difficult work. Smith’s scene preserves a question about agency that a short keyword can erase. The figure may be withholding action, but the posture itself is an action, holding opposed weights in a temporary arrangement.',
    '可以把这里的眼罩与宝剑八比较。宝剑八的人物被束缚，宝剑二的人物却主动握着武器。因此，同样的视觉细节能够参与不同处境：一边是限制，一边是持续维持均衡。这种区别使我们不必把所有蒙眼都解成否认现实。交叉双臂也不是空洞的消极，而是在做吃力的工作。史密斯的场景保留了关键词容易抹掉的主动性问题：人物可能暂不采取下一步，但姿态本身就是行动，正在把相反的重量维持于临时安排中。',
  ],
  'swords-03': [
    'Place the Three beside the Nine of Swords and a revealing difference appears. The Nine gives sorrow a room, a bed, and a human gesture; the Three removes those particulars and leaves a sign. One invites us to imagine a person’s experience, while the other makes the experience immediately recognizable as an emblem. Neither supplies a reliable biography. The Three’s clean geometry also gives form to something emotionally disorderly. That artistic choice helps explain its lasting memorability: the viewer can take in the entire design almost instantly, then keep returning to the discomfort of a bright, vulnerable centre set against impersonal blades and weather.',
    '把宝剑三放在宝剑九旁边，会看到关键区别。宝剑九给悲伤一个房间、一张床和人的动作；宝剑三移去这些具体条件，只留下标志。一张邀请我们想象个人体验，另一张则把体验变成一眼能认出的徽记。两者都没有提供可靠的个人传记。宝剑三清楚的几何结构，也给混乱情绪一种形式。这种艺术选择解释了它为何令人难忘：观者瞬间就能读完整个设计，却不断回到鲜亮脆弱的中心，与无情利刃和天气之间的不适对照。',
  ],
  'swords-04': [
    'This interior is a useful companion to the Nine’s bedroom. Both place the Sword suit beside a horizontal resting place, yet one composition is ordered and devotional while the other is interrupted by distress. The contrast shows how strongly Smith’s setting controls the emotional story. In the Four, even the blades have been arranged rather than wielded. The sculpted body cannot rush into the next scene. Its permanence invites the viewer to remain with the stillness for a moment. Reading it only as a quick break before returning to productivity misses the slower register of remembrance, separation from daily noise, and an encounter with time beyond immediate tasks.',
    '这处室内可以与宝剑九的卧室对照。两张牌都把宝剑放在水平的休息位置附近，但一张秩序井然、具有祈祷氛围，另一张则被痛苦打断。对比显示，史密斯如何通过环境决定情绪故事。在宝剑四中，剑也被安放，而不是挥舞。雕刻的身体无法赶往下一幕，其持久性邀请观者在静止中停留。若只把它读成返回工作前的短暂休息，就会遗漏记忆、离开日常喧闹，以及与即时任务之外的时间相遇的缓慢层次。',
  ],
  'swords-05': [
    'Compare the collected blades with those carried away in the Seven. Both images show a person controlling several weapons, but the Five includes the visible reaction of others. That social aftermath changes what possession means. Smith does not let the nearest figure occupy the whole story: distance, posture, and the turned backs of the other people remain part of the evidence. The viewer’s sympathy can move across the picture instead of remaining with the apparent winner. This makes the card particularly effective as an ethical image. Success can be counted in captured objects, yet the relationships damaged or abandoned are harder to put into the same account.',
    '可以把被收集的剑与宝剑七带走的剑比较。两幅图都有人掌控多把武器，但宝剑五加入了别人的可见反应。这种社会后果改变了占有的意义。史密斯没有让最近的人垄断故事：距离、姿态和其他人的背影仍属于证据。观者的同情能够在画面中移动，而不必停留在表面赢家身上。因此，这张牌特别适合成为伦理图像。成功可以通过得到的物件计数，受损或被放弃的关系却难以放进同一本账里。',
  ],
  'swords-06': [
    'Set this journey beside the Knight of Swords and the difference in tempo becomes clear. The Knight appears to force a way forward; the ferryman uses a route that can carry vulnerable passengers. Progress in the Six is organized around a vessel, a guiding person, and enough capacity for the load. It is a quietly cooperative image. The swords do not stop the crossing, but neither are they thrown away to make the picture cheerful. That artistic decision allows movement and unresolved difficulty to coexist. A viewer can acknowledge sadness in the seated figures while still noticing that a practical structure is already helping them travel.',
    '把这趟旅程与宝剑骑士放在一起，节奏差异就很明显。骑士像是在强行向前，船夫则利用能够承载脆弱乘客的路线。宝剑六的进展由船、引路人和足够载重能力组织起来，是安静的合作图像。剑没有阻止渡行，也没有被扔掉来强求愉快。这项艺术选择让移动与尚未解决的困难共存。观者可以承认乘客的悲伤，同时注意到一个实际结构已经在帮助他们前行。',
  ],
  'swords-07': [
    'The Seven is an instructive example of the difference between seeing and completing a story. We can count the carried swords, observe the glance, and locate the camp; we cannot hear an explanation from any participant. The viewer supplies the missing connection. Compared with the Five, where disappointed figures openly retreat, the Seven withholds the social response. That absence produces much of its fascination. It invites the mind to act like a detective, while also exposing the risk of reaching a verdict too quickly. Waite’s mixed list of meanings is therefore not just an inconvenience to modern readers: it preserves a real ambiguity in the picture’s construction.',
    '宝剑七很适合说明“看见”与“补完故事”的区别。我们能数剑、观察回望、找到营地，却听不到任何参与者的解释。缺失的连接由观者补上。相比宝剑五清楚表现沮丧者离去，宝剑七隐藏了社会反应，这种缺席形成了它的大部分魅力。它邀请头脑像侦探一样工作，同时暴露过早下结论的风险。因此韦特混杂的含义，并非只是让现代读者不便，而是保留了画面结构中真实存在的含混。',
  ],
  'swords-08': [
    'Compare this figure with the seated woman in the Two of Swords. Both are blindfolded, but only the Eight shows binding around the body and swords standing independently in the environment. The distinction matters: one scene involves maintaining a position, the other depicts being constrained within it. The Eight should therefore not be reduced to a lesson about choosing to worry. Its landscape can be examined without denying its difficulty. The viewer sees spaces that the figure cannot see, a difference in viewpoint that encourages assistance rather than superiority. Knowing more from outside a situation is not the same as finding it easy to move from within.',
    '可以与宝剑二坐着的女子比较。两者都蒙眼，只有宝剑八的身体被绑，剑也独立竖在环境中。区别很重要：一幅是维持姿态，另一幅是在处境中受限。因此，宝剑八不应被简化成“自己选择担心”的教训。我们可以检视环境，却不否认困难。观者看见人物看不见的空隙，这种视角差异应鼓励援助，而非优越感。从外面知道更多，不等于从里面移动就很容易。',
  ],
  'swords-09': [
    'The Four of Swords offers a revealing comparison: another interior, another horizontal place to lie down, but a very different relationship to stillness. The Four arranges the weapons around a motionless memorial; the Nine fills the upper darkness with blades while the person is painfully awake. Rest has been interrupted rather than peacefully entered. The body’s upright posture creates a break in the room’s horizontal lines. These compositional choices give distress a rhythm that the viewer can feel. They also show why the card need not depend on a supernatural claim to be affecting: its power comes partly from a recognizably human experience of being unable to settle.',
    '宝剑四提供了鲜明对照：同样是室内，同样有可平躺的位置，与静止的关系却不同。宝剑四围绕不动的纪念雕像安排武器；宝剑九则让利刃填满上方黑暗，而人物痛苦地醒着。休息被打断，而非平静进入。直起的身体打破房间的横线。这些构图选择让痛苦有了观者能够感到的节奏，也说明牌的感染力不必依赖超自然断言：它的力量部分来自一种可辨认的人类经验——无法安顿下来。',
  ],
  'swords-10': [
    'The difference from the Nine is not simply one additional sword. In the Nine, distress is held inside a waking person’s gesture; here the scene is bodily and external, almost theatrical in its finality. Smith also moves from a room to a landscape, giving the ending a horizon. This does not require a cheerful explanation of the fallen figure. It means that the picture contains more space than its most shocking detail. Looking at the whole composition rather than staring only at the blades allows the viewer to hold two observations together: something looks decisively over, and the surrounding world has not ceased to exist.',
    '与宝剑九的区别不只是多一把剑。宝剑九的痛苦保留在醒者的动作里；这里则是外在、身体性的场景，终结感近乎戏剧。史密斯也把室内移到风景中，让结束拥有地平线。这不要求为倒下的人编造快乐解释，而是说明图像的空间大于最惊人的细节。看整个构图，而不只盯着利刃，就能同时保留两项观察：某件事似乎确实结束了，周围世界却没有停止存在。',
  ],
  'swords-11': [
    'Compared with the King of Swords, the Page has no heavy throne to stabilize the body or public office to organize the gaze. The rough ground and moving air require continuous adjustment. Compared with the Pentacles Page, whose attention gathers around a single disc, this figure seems to scan the surroundings. Those differences make two kinds of learning visible: concentrated study and alert observation. Neither has to be superior in every situation. Smith’s court images become especially useful when viewed as relationships between bodies, objects, and environments, rather than as fixed descriptions of strangers whom the reader is expected to recognize by age or appearance.',
    '与宝剑国王相比，侍从没有厚重宝座稳定身体，也没有公职来组织目光。崎岖地面和流动空气要求持续调整。与把注意集中在单一圆盘上的星币侍从相比，这个人似乎正在扫描环境。这些差异使两种学习方式可见：集中研究与警觉观察。任何一种都不必在所有情况中更优越。把史密斯的宫廷图像看成人、物件与环境之间的关系，会比把它们当成根据年龄或外貌辨认陌生人的固定描述更有帮助。',
  ],
  'swords-12': [
    'The contrast with the Knight of Pentacles is one of the clearest comparisons in the deck. Both riders wear armour and display their suit, yet the Sword horse drives forward while the Pentacles horse holds its ground. Smith makes temperament readable through animal movement and the direction of the landscape. In the Sword image, even the tilted rider seems committed before the viewer has learned the purpose. That can make the scene exhilarating, but it also means important context is absent. The artwork leaves us with momentum rather than a full moral judgment. A fast response may be brave, mistaken, necessary, or some mixture that only the wider situation can establish.',
    '与星币骑士的对比，是牌组里最清楚的对比之一。两人都穿盔甲、展示花色，但宝剑马向前猛冲，星币马稳立不动。史密斯通过动物动作与风景方向让性情可读。在宝剑图中，倾斜的骑手仿佛在观者了解目的之前就已投入。这可以令人振奋，也意味着重要情境缺失。作品留下的是动势，而不是完整道德判断。迅速回应可能勇敢、错误、必要，也可能混合数种性质，需要更广泛处境才能确定。',
  ],
  'swords-13': [
    'The Queen’s gesture can be compared with the frontal King’s formal presence. Both raise a sword, but her free hand makes an explicit opening beyond the seat. That small difference helps the images resist being interchangeable portraits of intellectual authority. The Queen can seem to be addressing someone, even though the other person is absent. The viewer is left to imagine the quality of that encounter. A stern expression does not settle whether the response will be fair, cruel, protective, or candid. Keeping the hand, posture, and open space in view allows a fuller reading than treating an unsmiling woman as automatically unfeeling or hostile.',
    '可以把王后的动作与国王正面的正式姿态比较。两人都举剑，但她空着的手明确向座位之外打开。这个小差异，使两幅图不只是可互换的理性权威肖像。王后仿佛正在对某人说话，尽管那个人缺席。观者需要想象会面的性质。严肃表情并不能决定回应将是公平、残酷、保护或坦诚。把手、姿态与开放空间一起纳入视野，才能避免把不微笑的女性自动读成无情或敌对。',
  ],
  'swords-14': [
    'Compare the King’s still blade with the Knight’s raised weapon in motion. In one, force is being deployed; in the other, force is available through an established position. The difference turns speed into deliberation, but does not automatically turn power into wisdom. Smith’s frontal composition makes that issue difficult to avoid because the ruler appears to face us directly. We cannot simply watch him pass across a distant landscape. The image becomes an encounter with decision-making authority itself. That is why the comparison with Justice matters: the King can possess the means to decide, while fairness still requires reasons, proportion, and attention to those who must live with the decision.',
    '把国王静止的剑与骑士运动中举起的武器比较：一张在部署力量，一张通过既定位置保有可用力量。差异把速度转为审议，却不会自动把权力变成智慧。史密斯的正面构图让问题难以回避，因为统治者似乎直接面对我们。我们不能只看他从远景经过，而是与决策权威本身相遇。因此，与正义的比较尤其重要：国王可以拥有决定的手段，公平却仍需要理由、分寸，以及对必须承受决定者的关注。',
  ],
  'pentacles-01': [
    'Compare the offered coin with the tightly secured discs in the Four of Pentacles. Both concern material possibility, but their hands tell opposite stories: one opens, the other encloses. The Ace also differs from the Eight, where the emblem must be shaped by repeated work. Here the conditions for beginning appear first, before a craftsperson or owner has entered the scene. This helps explain the later emphasis on opportunity. The picture does not show a completed achievement. It shows a relationship waiting to happen between an available resource, a path, and someone who might take responsibility for using them. Its openness is more important than any guaranteed destination.',
    '可以把被提供的钱币与星币四紧紧守住的圆盘比较。两者都关乎物质可能，手却讲出相反故事：一边张开，一边包围。王牌也不同于星币八，那里标志必须通过反复劳动成形。这里首先出现开始的条件，工匠或主人还没有进入场景。这解释了后来为什么强调机会：图像没有展示完成的成就，而是展示等待发生的关系——资源、道路，以及可能负责使用它们的人。开放性比任何保证的目的地更重要。',
  ],
  'pentacles-02': [
    'The Four of Pentacles offers the opposite strategy: its figure keeps every disc fixed against the body, while the Two keeps both in motion. Smith makes two responses to material uncertainty visible through posture alone. The dancer’s flexible stance can be engaging, but the ships warn that the surrounding movement exceeds one person’s control. This prevents a useful reading from becoming a simple command to manage everything better. The scene can hold skill and instability together. Even an accomplished dancer needs conditions in which balance is possible, and even a careful schedule remains connected to a world that changes independently of the person attempting to maintain it.',
    '星币四提供相反策略：人物把每枚圆盘固定在身体旁，星币二则让两枚持续运动。史密斯仅用姿态，就使应对物质不确定性的两种方式可见。舞者的灵活很有吸引力，但船提醒我们，环境运动超过个人控制。这使阅读不至于变成“把所有事管理得更好”的简单命令。技巧与不稳定可以同时存在。再熟练的舞者也需要允许平衡的条件，再仔细的日程也仍与独立于个人意愿变化的世界相连。',
  ],
  'pentacles-03': [
    'The comparison with the Eight also changes how the architecture is understood. The Eight’s repeated objects display practice; the Three’s carved structure places skill inside something larger than the worker. The plan held by a visitor can be read as a bridge between an intended result and the knowledge needed to make it real. There is no need to assign a secret identity to each participant for that exchange to matter. The picture already shows attention moving between people. Smith has turned three counted emblems into an occasion when expertise becomes social: someone makes, someone observes, and the project requires these positions to meet rather than operate in isolation.',
    '与星币八比较，也会改变我们对建筑的理解。星币八的重复物件展示练习，星币三的雕刻结构则把技能放进比工匠更大的事物中。来者手中的图纸，可以看作预期成果与实现成果所需知识之间的桥梁。交流要有意义，并不需要给每个人安排秘密身份。图像已经展示注意力在人们之间流动。史密斯把三个计数标志转为专业能力进入社会的场合：有人制作，有人观察，项目要求这些位置相遇，而非各自孤立。',
  ],
  'pentacles-04': [
    'Placed beside the Six of Pentacles, the Four becomes one half of a conversation about how resources move. The Six opens a hand and distributes small coins; the Four uses hands and feet to stop movement. Neither picture alone provides a complete economic philosophy. Together they make the difference between storage and circulation tangible. The crown also complicates the seated figure: this is not merely someone holding an object but someone whose whole appearance has become organized around it. The pentacle above the head can make possession look like a governing idea. That is a visual inference, not a documented statement from Smith about the figure’s private thoughts.',
    '放在星币六旁边，星币四就成为关于资源如何流动的对话一半。星币六张手分发小钱，星币四用手脚阻止移动。任何一幅图都不能单独提供完整经济哲学，两者却让储存与流通的差异具体可感。王冠也使人物更复杂：不只是拿着物品的人，而是整个外观都围绕物品被组织起来的人。头上的星币可以让占有看起来成为支配观念。这是视觉推论，并非史密斯对人物内心的有据陈述。',
  ],
  'pentacles-05': [
    'The Six of Pentacles makes a revealing neighbour to this card. There, a giver and recipients occupy the same immediate space, and coins visibly pass between them. Here, value is behind glass and no exchange is shown. The difference makes access, not just quantity, central to the scene. Smith’s composition allows the viewer to feel how near something can be while remaining out of reach. It also places two people together rather than reducing poverty to an isolated individual. Those choices support questions about environment and relationship, while the missing doorway prevents a confident claim about why the travellers have not entered or what would happen if they tried.',
    '星币六是很有启发的邻牌。那里施予者与接受者处在同一空间，钱币清楚地在彼此间传递。这里价值在玻璃后面，没有交换发生。差异使“能否接近”与“有多少”同样重要。史密斯的构图让观者感到，东西可以如此近，却仍无法触及。她也把两个人放在一起，而不是把贫困缩成孤立个体。这些选择支持关于环境与关系的提问；缺失的门则阻止我们自信断言他们为什么没进去，或尝试后会发生什么。',
  ],
  'pentacles-06': [
    'Compare the transfer of small coins with the Five’s pentacles shining behind a window. The suit’s value moves from an inaccessible setting into a visible transaction. That change seems reassuring, but Smith does not remove the hierarchy between the participants. The scales remain in the giver’s hand, and the receiving figures are lower. The picture therefore allows two observations without forcing a choice between them: help is being offered, and one person controls its terms. A thoughtful reading can acknowledge the benefit of the gift while still examining fairness. This is more precise than declaring all charity either purely generous or inherently harmful on the basis of one small scene.',
    '可以把小钱的传递与星币五窗后的发光星币比较。花色的价值从不可触及的环境移入可见交易。这种改变似乎令人安心，但史密斯没有消除参与者的等级。秤仍在施予者手中，接受者位置更低。因此图像容许两项观察同时成立：帮助正在发生，而条件由一人掌控。周到阅读可以承认礼物的益处，同时检视公平，比根据一个小场景就宣布所有慈善纯粹善良或必然有害更准确。',
  ],
  'pentacles-07': [
    'The Eight of Pentacles shows work in progress through a repeated hand movement; the Seven shows the interruption of work through a sustained look. Smith gives each activity its own importance. The Seven’s figure is not pictured celebrating a completed harvest, so the familiar word success would settle the story too soon. Nor is the leaning posture enough to prove that the effort has failed. The visible crop sits between those conclusions. This interval is precisely what makes the scene useful: it grants evaluation a place within labour. Looking at results can be an active part of a process, even when it does not produce another object immediately.',
    '星币八通过重复的手部动作展示工作进行，星币七通过持续凝视展示工作被暂停。史密斯赋予两种活动各自的重要性。星币七没有庆祝完成收成，因此“成功”一词会过早结束故事；倚靠的姿态也不足以证明努力失败。可见的作物位于两种结论之间。正是这段间隔使场景有用：它给劳动中的评估留下位置。检视结果可以是过程的积极部分，即使它没有立即生产另一个物件。',
  ],
  'pentacles-08': [
    'The contrast with the Three of Pentacles is unusually explicit because Waite himself asks readers to make it. In the Eight, the scene gathers around a single person and a repeated task; in the Three, a larger structure and other people give the craft a public setting. Smith does not need to show a certificate or a title to make that difference visible. The worker’s place in a social process changes through surroundings and attention. This also explains why the Eight can remain meaningful after someone has become experienced: focused practice is an activity, not merely a low-status stage that a successful person must permanently leave behind.',
    '与星币三的对照特别明确，因为韦特本人要求读者这样比较。星币八围绕一个人与重复任务聚集，星币三则由更大结构与其他人赋予技艺公开环境。史密斯无需画证书或头衔，便使差异可见。工匠在社会过程中的位置，通过环境与注意力改变。这也解释为什么有经验者仍能从星币八得到意义：专注练习是一种活动，不只是成功者必须永久离开的低地位阶段。',
  ],
  'pentacles-09': [
    'The Ten of Pentacles places several generations together around an entrance, while the Nine concentrates on one person inside a cultivated space. This does not make one form of wellbeing better than the other. It makes two different relationships to abundance visible: a private enjoyment and a shared continuity. The Nine’s bird also gives the figure something to attend to besides the discs in the vines. Wealth is experienced through surroundings, living things, and the ability to pause. Smith’s scene can therefore be appreciated without deciding that the figure is lonely, that no one helped create the garden, or that solitude must always represent complete independence.',
    '星币十让几代人聚在入口周围，星币九则专注于培育空间中的一个人。这不使任何一种幸福形式更高贵，而是让与丰饶的两种关系可见：私人的享受与共同的延续。鸟也让人物除了藤蔓间圆盘之外，还有生命需要关注。财富通过环境、活物与停留的能力被体验。因此，我们可以欣赏场景，而不必断言人物孤独、花园无人帮助建成，或独处总是代表完全独立。',
  ],
  'pentacles-10': [
    'Compare this dispersed family scene with the Four’s compact figure holding every disc close. In the Four, resources are secured against one body; in the Ten, the emblems spread across people, animals, and architecture. That compositional difference makes ownership feel less isolated. It also leaves room for complexity. The people are not all attending to the older figure, and their different directions prevent the household from becoming a perfectly synchronized tableau. Smith gives continuity the texture of ordinary life, where generations share a place without sharing every concern. The resulting abundance is a network of relationships rather than a single moment of personal triumph.',
    '可以把这个分散家庭场景与星币四紧抱圆盘的人比较。星币四让资源紧贴一个身体，星币十则让标志铺在人、动物与建筑之间。构图差异使所有权不那么孤立，也保留复杂性。不是所有人都关注老人，不同方向避免家庭成为完美同步的舞台群像。史密斯让延续具有日常质感：不同世代共享地方，却不共享每项关切。因此丰饶成为关系网络，而非个人胜利的一刻。',
  ],
  'pentacles-11': [
    'Compare the Page’s raised gaze with the Knight’s outward presentation of the same emblem. Waite notices that distinction: one studies, the other displays. Smith makes the difference bodily through the hands, face, and relation to the landscape. The Page’s interest is not yet tied to a public achievement. Something ordinary has become worthy of close attention. That is why this quiet court card can feel more open than an image of established authority. The learning is still in motion, and its eventual use has not been settled. The picture permits curiosity before a practical outcome, an especially useful nuance in a suit often reduced to getting results.',
    '可以把侍从朝上的凝视与骑士朝外展示同一标志比较。韦特注意到一人在研究，另一人在展示。史密斯通过手、面孔及与风景的关系，让区别成为身体性的。侍从的兴趣尚未绑定公开成就，普通事物已经值得细看。因此，安静的宫廷牌能比既定权威更开放。学习仍在进行，最终用途未定。图像容许实际结果之前先有好奇，这是在常被简化为取得成果的花色里尤其有用的细节。',
  ],
  'pentacles-12': [
    'The Sword Knight offers an almost opposite account of movement: the horse stretches into a charge, the rider leans, and the landscape seems driven by wind. Here the heavier horse holds its position and the field looks worked rather than swept past. Both pictures can represent capacity, but Smith refuses to make capacity look identical in every suit. The Pentacles Knight may seem less exciting at first glance because the important action is implied through endurance. A completed task often depends on precisely the qualities that a dramatic image would skip: carrying weight, returning to a responsibility, and remaining available after the first burst of enthusiasm has faded.',
    '宝剑骑士几乎给出相反的运动叙述：马伸展冲锋，骑手俯身，风景仿佛被风推动。这里较厚重的马稳守位置，田野像经过耕作，而非被飞快掠过。两者都能代表能力，但史密斯不让各花色的能力看起来相同。星币骑士初看可能不那么刺激，因为重要行动通过耐力暗示。任务完成往往依赖戏剧图像会跳过的品质：负重、再次回到责任，以及最初热情消退后仍然在场。',
  ],
  'pentacles-13': [
    'The Queen’s hold on the pentacle differs from the Four’s enclosure of the same kind of object. Both keep it close, yet the Queen’s surroundings remain open to growth and small animal life. Her gesture does not require every limb to become a guard. That difference helps separate care from anxious possession without claiming that the picture reveals a person’s hidden psychology. The garden also makes authority feel dependent on an environment that must be maintained. Comfort is not simply commanded from a throne. It exists through relationships between attention, living conditions, and the objects that support daily life, which is why this ruler can be read through ordinary acts rather than grand declarations.',
    '王后托着星币的动作，与星币四包围同类物件不同。两者都把物品放近，王后环境却仍向生长与小动物开放。她无需让每个肢体都成为守卫。差异帮助区分照料与焦虑占有，却不声称画面能揭示隐藏心理。花园也使权威显得依赖需要维护的环境。舒适不能只由宝座发令产生，它通过注意、生活条件和支持日常的物件之间的关系存在，因此这位统治者可以通过普通行动，而非宏大宣言被理解。',
  ],
  'pentacles-14': [
    'Compared with the Ace’s offered disc and open path, this King represents a setting in which resources have gathered into an established arrangement. The image is full rather than expectant. Yet the dense vines can be read in more than one way: as flourishing abundance or as an environment so comfortable that movement becomes difficult. Smith’s composition permits that tension without declaring a verdict. The King’s practical intelligence is most interesting when it remains alive to changing conditions. Looking back toward the Page’s concentrated curiosity reminds us that a court rank need not erase the earlier skills of attention and learning on which capable leadership continues to depend.',
    '与王牌提供的圆盘及开放道路相比，这位国王呈现资源已汇聚成既定安排的环境。画面是充实的，而非等待的。茂密藤蔓却能有不止一种理解：欣欣向荣的丰饶，或舒适得使移动困难的环境。史密斯容许这种张力，却不宣布判决。国王的实际智慧，只有继续留意条件变化才最有意思。回看侍从专注的好奇，也提醒我们宫廷等级不必抹去注意与学习；有能力的领导仍持续依赖这些基本技巧。',
  ],
};
const entries: Entry[] = [
  {
    id: 'swords-01',
    teaser: ['A crown rests on a blade: victory arrives with a question about how power will be used.', '王冠落在剑尖上：胜利也带来了如何运用力量的问题。'],
    past: ['An ace concentrates the identity of its suit in one emblem. Here that makes the sword unusually exposed: no soldier, monarch, or opponent tells us whose cause it serves. The crown links it to authority and victory. Waite describes force and conquest, extending that force to love as well as hatred. His account is more ambivalent than the reassuring modern shorthand of a bright idea or sudden clarity. A successful argument can be powerful without being kind.', '王牌把花色的身份集中在单一标志上。因此这把剑格外醒目：没有士兵、君主或敌手告诉我们，它服务于谁的事业。王冠把剑与权威和胜利连接起来。韦特谈到力量与征服，认为这种力量既可能服务于爱，也可能服务于恨。他的解释比今天常见的“灵光一现”或“思路清晰”更复杂：赢得争论的力量，不一定同时具有善意。'],
    scene: ['Smith places the upright sword above a rough mountain landscape. The hand appears out of cloud, so the composition feels like an offering or appearance rather than a scene from a battlefield. The vertical blade makes the whole picture feel decisive. Yet the surrounding barren heights do not show what will be built with this power. Looking from the crown down to the ground changes the story from celebrating achievement to wondering what achievement actually makes possible.', '史密斯让直立的宝剑出现在崎岖山地之上。手从云中伸出，整个构图更像一种呈现或赠予，而不是战场片段。竖直的剑使画面显得果断，但下方的荒山并未告诉我们，这份力量能建设什么。把目光从王冠移向大地，故事就从庆祝成就，转为追问成就能够开启什么。'],
    symbols: [
      [['Crown', '王冠'], ['The crown signals triumph and authority. Waite leaves open a higher significance, rather than providing a single complete decoding of it.', '王冠指向胜利与权威。韦特保留了更高层面意义的可能，并没有给它唯一、完整的解码。']],
      [['Cloud-born hand', '云中之手'], ['No identifiable person owns the weapon. As a visual reading, this shifts attention from personal status to the potential of the sword itself.', '握剑者没有可辨认的身份。从画面看，这让注意力从个人地位转向宝剑本身的潜能。']],
      [['Mountain peaks', '山峰'], ['The hard landscape makes a striking contrast with the ceremonial crown. It can suggest that a clear beginning still faces difficult terrain.', '坚硬的山地与华丽王冠形成对照，可以使人想到：即使起点清晰，前方仍有难走的道路。']],
    ],
    reflection: ['For reflection, the card can ask what a new insight will cut through, and what it might accidentally cut away. Clarity is useful when it reveals a real distinction; certainty becomes less useful when it silences other people. This is a contemporary way to work with the picture, not a claim that its early ancestors taught a lesson about communication. Its history encourages a richer reading than simply calling every sharp thought a victory.', '用于反思时，这张牌可以让我们思考：新发现能斩断什么，又可能误伤什么？清晰的判断能够揭示真正的区别；如果确定感使别人无法开口，它的价值就会下降。这是今天与图像相处的一种方式，并不意味着早期祖先牌就在传授沟通课程。了解它的历史，可以避免把每一个尖锐念头都称为胜利。'],
    detail: ['Waite’s entry explicitly allows force in both love and hatred. The Ace is powerful before it is automatically benevolent.', '韦特明确说，这份力量既能出现在爱中，也能出现在恨中。王牌首先是强大的，并非天然仁慈。'],
  },
  {
    id: 'swords-02',
    teaser: ['Two crossed blades hold a fragile peace while the sea keeps moving behind them.', '两把交叉的剑维持着微妙的平衡，身后的海仍在流动。'],
    past: ['Two swords could once be read first as a number and a suit. In this deck, their relationship becomes bodily: a seated figure must hold both weapons in balance. Waite links the card with equipoise and even friendship, but qualifies its harmony as an armed concord. That is a revealing contrast with the now familiar idea of indecision. The historical text allows a truce as well as a blocked choice; the swords need not be rival options in every reading.', '两把剑原本首先标明数字和花色。在这副牌中，它们的关系变成身体的动作：坐着的人必须同时保持两把武器的平衡。韦特把它与均衡、甚至友谊相连，但限定为一种带着武器的和谐。这与今天常见的“犹豫不决”不同。历史文字允许我们看见休战，也允许看见受阻的选择；两把剑并非在每次解读中都必须代表两个选项。'],
    scene: ['The figure sits directly before us, blindfolded, while water, rocks, and a crescent moon occupy the background. Her arms close across her chest, turning the weapons into both protection and effort. Nothing visibly attacks her. That absence is part of the tension: are the blades keeping danger outside, or keeping experience away? Smith gives us a held moment rather than a completed event, so the next movement remains unresolved.', '人物蒙着眼，正面坐在观者之前，背景有海水、礁石和弯月。双臂交叉在胸前，宝剑既成为保护，也意味着持续用力。画面没有明显的攻击者。这种缺席正是紧张感的一部分：剑是在阻挡危险，还是在隔绝经验？史密斯呈现的是被保持住的一刻，而不是已经完成的事件，下一步动作仍未决定。'],
    symbols: [
      [['Blindfold', '眼罩'], ['The covered eyes limit visible information. They can suggest deliberate withdrawal or uncertainty, but the picture alone cannot tell us which.', '眼罩限制了可获得的信息，可以联想到主动退避或不确定，但单靠画面无法确定是哪一种。']],
      [['Crossed swords', '交叉的剑'], ['The blades form a balanced barrier. Their symmetry offers order while the weight of holding them hints that the arrangement requires effort.', '剑构成平衡的屏障；对称带来秩序，维持动作所需的力量却提醒我们，这种状态需要付出。']],
      [['Sea and rocks', '海与礁石'], ['The background contains movement and obstacles outside the figure’s immediate attention. A modern reading may connect that contrast with neglected context.', '背景包含人物暂时没有关注的流动与障碍。现代阅读可以把这种对照理解为尚未顾及的环境。']],
    ],
    reflection: ['This card becomes more interesting when peace and avoidance are allowed to coexist. A pause can protect a conversation until both people are ready; it can also become a way to postpone a necessary fact. Rather than demanding an immediate decision, the image invites a practical question: what information, rest, or reassurance would make lowering one blade possible? That reflective question grows from the composition, while Waite’s armed harmony reminds us that balance is not always relaxation.', '当我们容许和平与回避同时存在，这张牌就更有意思。暂停能够保护一场尚未准备好的谈话，也可能变成拖延必要事实的方法。与其要求立刻作决定，不如问：需要什么信息、休息或安心感，才能放下一把剑？这个反思问题来自构图；韦特所说的持械和谐则提醒我们，平衡未必等于放松。'],
    detail: ['Waite includes friendship among the possibilities. Reading only “cannot decide” loses the card’s older tension between alliance and self-protection.', '韦特把友谊列为可能含义。若只读成“无法决定”，就会遗漏它在结盟与自我保护之间的张力。'],
  },
  {
    id: 'swords-03',
    teaser: ['A heart, three blades, and rain tell a story without showing a single human face.', '一颗心、三把剑与雨，不用任何人物面孔就讲出了故事。'],
    past: ['The Three of Swords is unusual among the numbered scenes because it works as an emblem rather than a small drama of people. Waite describes separation, rupture, and absence, treating the image as immediately legible. Its directness should not be confused with a documented single origin for every later interpretation. A heart pierced by weapons can gather many associations, but identifying one specific religious or romantic source would require evidence beyond the resemblance itself.', '宝剑三在数字牌中很特别：它更像一个徽记，而不是有人物参与的小戏剧。韦特谈到分离、破裂和缺席，认为图像本身已经足够明白。这种直接性不应被误认成所有后世解释都有一个明确起源。被利器穿透的心可以引发许多联想，但若要断言某个特定宗教或爱情故事就是它的来源，仍需要超越外观相似的证据。'],
    scene: ['Smith suspends a red heart against grey clouds and diagonal rain. One sword runs down the centre and two angle through it, giving the design a severe symmetry. There is no visible body to establish whether the hurt concerns lovers, friends, relatives, or an idea. That omission makes the emblem widely adaptable. It also explains why a strong emotional response can arrive before any handbook is opened: the picture makes piercing and exposure almost impossible to overlook.', '史密斯把红心悬在灰云与斜雨之前。一把剑穿过中央，另外两把斜向交叉，形成严厉的对称。没有身体能告诉我们，伤痛来自恋人、朋友、亲人，还是某种信念。这个留白使徽记具有广泛的适用性，也解释了为什么人们还没打开说明书，就可能产生强烈感受：穿透与暴露在图像中几乎无法被忽略。'],
    symbols: [
      [['Red heart', '红心'], ['The isolated heart gives emotion a visible shape. Its redness separates it sharply from the weather and makes vulnerability the centre of attention.', '独立的心让情绪有了可见形状。鲜红与天气形成强烈对照，使脆弱成为焦点。']],
      [['Three blades', '三把利刃'], ['All three cross the same central form. They need not stand for three people; that popular inference is not established by Waite’s description.', '三把剑都穿过同一颗心，并不必然表示三个人；韦特的文字没有确立这种常见推断。']],
      [['Rain', '雨'], ['The rain extends the mood beyond the heart. It can be read as grief or a difficult atmosphere, rather than evidence about literal weather.', '雨让心的情绪扩展到周围环境，可以读作悲伤或艰难氛围，而不是现实天气的证据。']],
    ],
    reflection: ['A useful contemporary reading makes room for hurt without prescribing its cause. Naming a disappointment may be more helpful than hunting for a hidden betrayal. The absence of identifiable characters is important here: it keeps the image from proving a story about someone else. Historically, Waite’s language is broader than romance, including distance and division. The card therefore offers a way to consider a broken expectation or painful truth as well as a relationship ending.', '今天使用这张牌时，可以承认伤痛，而不急着规定原因。说清楚失望是什么，可能比寻找隐藏的背叛更有帮助。没有明确人物身份这一点很重要：图像无法证明关于别人的故事。韦特的词汇也比爱情宽广，包括距离与分裂。因此，它同样可以帮助我们思考落空的期待、难以接受的事实，而不只是关系结束。'],
    detail: ['There are no people in this scene. The common assumption that three swords must mean a love triangle goes beyond the evidence of the picture.', '画面没有人物。把三把剑必然解释成三角恋，已经超出了图像能够提供的证据。'],
  },
  {
    id: 'swords-04',
    teaser: ['What looks like a sleeping knight is a stone memorial, and that changes the story of rest.', '看似安睡的骑士其实是石制卧像，这让休息的故事变得不同。'],
    past: ['Waite identifies the central figure as a knight’s effigy upon a tomb. That description connects the illustration with a recognizable memorial form rather than a literal person taking a nap. His meanings include retreat, solitude, vigilance, and the tomb itself. The now familiar emphasis on recovery is a reflective development from this stillness, not the whole historical account. Remembering the monument allows questions about memory and contemplation to stand beside questions about fatigue.', '韦特把中央人物明确称为墓上的骑士卧像。因此，这幅图与可辨认的纪念雕塑形式相连，而不是一个正在打盹的人。他列出的含义包括退隐、独处、警觉，以及墓穴本身。今天常见的恢复精力，是从静止发展出来的反思方向，并非历史解释的全部。记住这是一座纪念物，就能让记忆与沉思，和疲惫的问题并列存在。'],
    scene: ['The golden figure lies with joined hands beneath three wall-mounted swords, while the fourth runs horizontally below. A stained-glass window brings a small scene of colour into the quiet architectural space. The arrangement slows the eye: the upright weapons no longer participate in a confrontation, and the horizontal sword echoes the body. Smith turns the suit’s usual tension into suspension. Nothing has vanished, but movement has been deliberately removed from the foreground.', '金色卧像双手合拢，上方墙上悬着三把剑，第四把在下方横放。彩色玻璃窗把一小块鲜明的场景带入安静的建筑空间。构图让视线慢下来：竖剑不再参与冲突，横剑则呼应身体的方向。史密斯把宝剑常见的紧张转化为悬置；事物没有消失，但前景中的运动被刻意抽离。'],
    symbols: [
      [['Joined hands', '合拢的双手'], ['The hands belong to the prayerful pose of the effigy. They introduce contemplation rather than simply showing physical exhaustion.', '双手属于卧像祈祷式的姿态，引入的是沉思，而不只是身体耗尽。']],
      [['One horizontal sword', '横放的一把剑'], ['The fourth sword lies apart from the three above. Its changed direction helps organize a picture of quiet rather than active combat.', '第四把剑与上方三把分开，方向的改变使画面趋向安静，而不是正在发生的战斗。']],
      [['Stained glass', '彩色玻璃'], ['The coloured window locates the image in a devotional setting. It gives the room a life beyond the silent stone figure.', '彩色窗户使画面具有宗教空间的氛围，也让静默石像之外仍保留着生活的存在。']],
    ],
    reflection: ['The modern invitation to rest works best when it respects the card’s deliberate pause. It is not a promise that doing nothing solves everything. Instead, one might ask what needs a protected interval: a difficult conversation, a demanding project, or a mind that has not stopped rehearsing conflict. The historical memorial setting adds another question: what deserves acknowledgement before moving on? Rest can include remembering and making sense of experience, not merely becoming ready to perform again.', '现代的休息邀请，最好尊重这张牌中有意识的暂停。它并不保证什么都不做就能解决问题，而是让人思考：什么需要一段受保护的时间——艰难谈话、繁重项目，还是不断重演冲突的头脑？纪念雕像的背景还增加一个问题：继续前进之前，有什么值得被认真承认？休息可以包含记忆与理解，而不只是重新具备工作的能力。'],
    detail: ['Waite calls the figure an effigy. The stillness is sculpted, making this a picture of contemplation around a memorial as well as a modern symbol of rest.', '韦特称人物为卧像。静止是雕刻出来的，因此这里既是围绕纪念物的沉思，也能成为现代的休息象征。'],
  },
  {
    id: 'swords-05',
    teaser: ['Someone has won the swords, but the departing figures make victory feel strangely empty.', '有人赢得了宝剑，离去的人却让胜利显得空落。'],
    past: ['The older counting function of five blades becomes a distribution of possessions: some swords are held, others abandoned. Waite emphasizes the central figure’s possession of the field and the dejection of those walking away. His interpretation centres on loss and dishonour rather than uncomplicated success. The important historical detail is that the victor’s position is visible, while moral approval is not. Holding the weapons does not make the person a model to imitate.', '五把剑原本的计数作用，在这里变成物品的分配：一些被拿走，一些被遗弃。韦特强调中央人物占有场地，以及离去者的沮丧。他的解释围绕损失与失誉，而不是简单的成功。重要之处在于，胜者的位置虽然可见，道德上的认可却不存在。拿着武器，并不使这个人成为值得模仿的榜样。'],
    scene: ['Smith arranges the figures at different depths, so our attention moves from the nearby collector of swords toward the retreating people and open water. The wind-torn clouds intensify the uneasy aftermath. We do not witness the argument or contest that came before, and the card does not identify a rightful owner for every blade. That missing beginning makes the consequences more prominent than the score. The scene asks us to look at what remains between people after a confrontation.', '史密斯把人物放在不同远近的位置，让目光从近处收剑者转向离去的人和开阔水面。被风撕动的云增加了事后不安。我们没有看见之前的争论或比赛，牌也没有说明每把剑原来的合法主人是谁。开头的缺失，使后果比输赢更突出。画面邀请我们看见冲突结束后，人际之间究竟剩下什么。'],
    symbols: [
      [['Collected swords', '收集的宝剑'], ['Possession gives the foreground figure an advantage. As a reflective reading, it can expose the difference between winning resources and preserving trust.', '占有使前景人物获得优势；用于反思时，它能揭示赢得资源与保住信任之间的区别。']],
      [['Retreating people', '离去的人'], ['The distant figures give the scene a social cost. Their withdrawal prevents the image from functioning as a simple celebration of triumph.', '远处人物让场景显现社会代价。他们的离去，使图像无法成为单纯的胜利庆典。']],
      [['Restless sky', '躁动的天空'], ['Jagged clouds keep the atmosphere unsettled even though the confrontation appears over. The weather supports mood rather than proving a hidden event.', '破碎的云让结束后的环境仍不安定。天气在这里强化情绪，而不能证明某个隐藏事件。']],
    ],
    reflection: ['A present-day reading can consider whether insisting on the last word would damage something more valuable. It can equally recognize that leaving an unhealthy contest is sometimes a deliberate choice, not a failure. The picture does not require us to identify with its closest figure. Trying the viewpoint of each participant makes its ethical problem more interesting: what would count as a good outcome if everyone’s experience mattered? That question extends the artwork without pretending to recover a medieval rule.', '今天可以借这张牌思考：坚持说最后一句，是否会伤害更重要的东西？也可以承认，离开一场不健康的竞赛，有时是主动选择，而非失败。我们不必把自己等同于最近的那个人。尝试每位参与者的视角，会让伦理问题更丰富：如果每个人的经验都重要，怎样才算好结果？这是从作品延伸出的提问，并不是找回了某条中世纪规则。'],
    detail: ['The action is largely over before we enter the picture. Smith makes the aftermath, rather than the fight, carry the meaning.', '我们进入画面时，主要行动已经结束。史密斯让后果，而非打斗本身，承担了意义。'],
  },
  {
    id: 'swords-06',
    teaser: ['The swords travel with the passengers: crossing the water does not mean leaving every burden behind.', '剑与乘客一同渡水：离开原地，并不等于把所有负担留下。'],
    past: ['Waite’s description is unusually practical: a ferryman transports passengers to another shore, with a manageable load and a smooth passage. His meanings include travel by water and the idea of a route or expedient. The familiar modern language of emotional transition grows naturally from the image, but it expands a text concerned with actual passage. The card’s history therefore includes an ordinary human technology, the boat, as well as the abstract experience of change.', '韦特的描述格外实际：摆渡人载着乘客驶向对岸，载重不难承受，航程也平稳。他列出的含义包括水路旅行、路线与解决办法。现代常见的情绪转变，很自然地从画面生长出来，但它扩展了原本文字对实际渡行的关注。因此，这张牌的故事既包含抽象的变化，也包含一项普通的人类技术——船。'],
    scene: ['Smith shows the passengers mostly from behind. A cloaked adult bends forward beside a smaller figure, while a standing boatman propels them onward. Six upright swords occupy the bow, becoming part of the cargo rather than weapons in use. The destination remains a distance away. The subdued posture prevents the journey from looking like a festive adventure, yet the boat is moving. That combination gives the image its particular tenderness: progress can happen before relief has fully arrived.', '史密斯主要从背后描绘乘客。披衣的成年人俯身坐在较小的人旁边，站立的船夫推船前进。六把竖剑占据船头，成为行李的一部分，而不是正在使用的武器。目的地仍在远处。低垂的姿态使旅程不像欢快冒险，但船确实在移动。这种组合产生了特别的温柔：完整的轻松尚未到来，前进已经发生。'],
    symbols: [
      [['Passengers seen from behind', '背向观者的乘客'], ['The hidden faces leave their personal history open. The viewer can notice companionship and vulnerability without assigning a specific family story.', '看不见的面孔保留了人物经历的开放性。我们可以看见陪伴与脆弱，而不必替他们指定家庭故事。']],
      [['Swords in the boat', '船上的剑'], ['The suit travels inside the vessel. Modern readers often see carried concerns here, but Waite does not label each blade as a particular memory.', '宝剑随船同行。现代读者常联想到被带着走的心事，但韦特没有把每一把剑指定为某段记忆。']],
      [['Distant shore', '远岸'], ['The shore gives the movement a destination without showing arrival. It keeps the emphasis on being in passage rather than already safe at home.', '岸让移动有了方向，却没有展示抵达，使重点停留在过渡过程，而不是已经安全归家。']],
    ],
    reflection: ['The picture can encourage a modest idea of progress: a quieter setting, practical assistance, or a next step that is possible today. It does not demand that every feeling be resolved before moving. The boatman also matters. Change is not always a solitary act of courage; it may depend on someone who knows the route or can share the work. That reading draws from the visible cooperation while preserving the difference between a hopeful interpretation and a promised outcome.', '画面可以支持一种朴素的进步：更安静的环境、实际的帮助，或今天能够做到的一步。它不要求所有情绪都先得到解决。船夫也很重要。变化并不总是孤身一人的勇敢行动，有时需要熟悉路线或愿意分担工作的人。这种理解来自可见的合作，同时保留希望性的解释与结果保证之间的区别。'],
    detail: ['Waite explicitly considers the ferryman’s workload manageable. The scene contains practical competence, not only sadness or escape.', '韦特特意指出船夫能够承受这份工作。画面里不仅有悲伤或离开，也有实际能力。'],
  },
  {
    id: 'swords-07',
    teaser: ['Five swords go with the traveller, two stay behind, and the story refuses to give a simple verdict.', '五把剑被带走，两把仍留在原地，故事拒绝给出简单判词。'],
    past: ['Waite admits that this card’s meanings do not agree neatly with one another. He lists plans, attempts, hope, confidence, quarrelling, and a project that might fail. That admission is historically valuable: the handbook itself does not present an unambiguous dictionary entry for dishonesty. The image certainly invites suspicion, but the now common label of theft is only one way to settle a scene whose original written explanation remains deliberately uncertain.', '韦特承认，这张牌的解释并不容易彼此协调。他列出计划、尝试、希望、信心、争执，以及可能失败的项目。这种承认具有历史价值：说明书本身没有把它写成“欺骗”的唯一词条。画面确实引人怀疑，但今天常见的“偷窃”标签，只是为一个原有文字仍显得含混的场景作出结论的一种方式。'],
    scene: ['A figure moves away from a camp carrying five swords while looking back. Two more remain planted in the ground. Smith gives the body a light, almost theatrical step, which sits uneasily beside the dangerous blades. The backward glance makes intention feel important, but cannot reveal it. We have no witness statement from the camp and no caption announcing ownership. Instead of resolving the mystery, the composition makes planning, partial success, and possible exposure visible at the same time.', '一个人带着五把剑离开营地，同时回头张望，另两把仍插在地上。史密斯赋予身体轻巧、近乎舞台化的步态，与危险的利刃形成不安的组合。回望使动机显得重要，却无法揭示动机。营地没有证人发言，也没有文字宣布所有权。构图没有解开谜团，而是同时呈现谋划、部分成功，以及可能暴露的风险。'],
    symbols: [
      [['Backward glance', '回头一望'], ['Looking back suggests attention to what is being left behind. It can imply caution or concealment without proving either motive.', '回望说明人物关注身后之事，可以暗示谨慎或隐瞒，却不能证明其中任何一种动机。']],
      [['Five carried, two left', '带走五把，留下两把'], ['The uneven division makes the action incomplete. A plan may obtain something while leaving obligations or difficulties unresolved.', '不均匀的分配使行动显得未完成。一项计划可能有所收获，同时留下责任或困难。']],
      [['Camp', '营地'], ['The tents place private action beside a larger group. This gives the scene a question about cooperation, rules, and responsibility to others.', '帐篷把个人行动放在群体旁边，使场景涉及合作、规则，以及对他人的责任。']],
    ],
    reflection: ['For reflection, this is a useful place to examine a strategy without jumping to accusations. What is the plan intended to accomplish? Which part cannot be discussed openly, and why? Sometimes discretion protects a legitimate boundary; sometimes secrecy shifts costs onto someone else. The picture allows both questions. Waite’s uncertainty is a reminder to seek ordinary evidence before making claims about another person. A compelling image can help us ask better questions without supplying the missing facts itself.', '用于反思时，可以检视策略，而不急着指控别人：计划想完成什么？哪一部分无法公开讨论，为什么？谨慎有时保护合理界限，秘密有时却把代价转嫁给别人。画面容许两种提问。韦特的犹疑提醒我们，在判断他人之前寻找日常证据。引人入胜的图像能够帮助提出更好的问题，却不能自行补上缺失的事实。'],
    detail: ['Waite calls the design uncertain in meaning. Treating the Seven as automatic proof of deception erases that explicit historical ambiguity.', '韦特直接说图像的意义不确定。若把宝剑七当作欺骗的自动证据，就抹去了这份明确的历史含混。'],
  },
  {
    id: 'swords-08',
    teaser: ['The prisoner is surrounded by swords, yet the original handbook stresses that the confinement is temporary.', '人物被宝剑围绕，但原说明书强调，这种禁锢并非不可改变。'],
    past: ['Waite describes a bound and blindfolded woman, then immediately qualifies the scene: her confinement is temporary rather than beyond remedy. That qualification is often more useful than his severe divinatory list. The card did not arrive with a simple doctrine that every obstacle is imaginary or self-created. The visible restraints are real within the picture. What remains open is their duration and the possibility of help, movement, or a changed situation.', '韦特先描述被束缚、被蒙眼的女子，随即加以限定：她只是暂时受困，并非永远无法脱身。这句话往往比他严厉的占卜词表更有帮助。这张牌并没有提出“一切障碍都是想象或自找的”这样简单的教条。在画面内部，束缚确实存在；尚未确定的是它会持续多久，以及是否能获得帮助、移动或处境改变。'],
    scene: ['Smith leaves space around the figure’s feet and between the upright blades. The ground is uneven and wet, while a distant building rises beyond. The result is an enclosure that feels intimidating without forming a seamless wall. The blindfold prevents the figure from assessing the available space. This makes information as important as force: the visual problem is not simply that swords exist, but that the person cannot clearly see the arrangement around her.', '史密斯在人物脚边和竖剑之间留下空间。地面湿润且不平，远处有建筑升起。围困显得吓人，却不是没有缝隙的墙。眼罩让人物无法判断周围还有哪些空间。因此，信息变得与力量同样重要：问题不只是宝剑存在，还在于她看不清它们的排列。'],
    symbols: [
      [['Bindings', '束带'], ['The restraints make limitation visible. They invite attention to actual conditions and support needs, not blame for failing to escape quickly.', '束带使限制可见，提醒我们关注真实条件与支持需求，而不是责备人物为何没有迅速逃开。']],
      [['Gaps between swords', '剑之间的空隙'], ['The barrier is not continuous. As a visual reading, those gaps preserve the possibility that more options exist than the figure can currently perceive.', '屏障并不连续。从图像看，空隙保留一种可能：可行选项比人物当下能够察觉的更多。']],
      [['Distant building', '远方建筑'], ['The inhabited world remains visible beyond the immediate difficulty. It gives the scene a wider setting rather than making confinement the whole universe.', '困难之外仍能看见有人居住的世界。它扩展了环境，使困境不至于成为全部世界。']],
    ],
    reflection: ['A compassionate modern reading asks which constraint is external, which is uncertain, and what assistance would clarify the difference. It need not demand a dramatic act of willpower. One reliable fact, a practical ally, or a smaller next step can change how a difficult situation is understood. The historical text supports leaving the future open, but it does not promise immediate freedom. Respecting both the bindings and the gaps makes the image more humane than a slogan about positive thinking.', '温和的现代阅读可以问：哪些限制来自外部，哪些还不确定，什么帮助能辨明两者？它不必要求惊人的意志力。一条可靠事实、一位实际的盟友，或更小的一步，都可能改变我们理解困难的方式。历史文字支持保留未来的开放性，却不保证立刻自由。同时尊重束带与空隙，比一句“积极思考就好”更有人情味。'],
    detail: ['The earliest accompanying description already leaves room for release. Hope is not merely a later attempt to soften this frightening scene.', '最早的配套描述就留下了脱困空间。因此，希望并非后来为了安慰人而硬加上去的内容。'],
  },
  {
    id: 'swords-09',
    teaser: ['Nine blades hang above a bed, turning the quietest room into a theatre of distress.', '九把剑悬在床上方，让最安静的房间变成痛苦的剧场。'],
    past: ['Waite describes someone sitting up in lamentation and uses strongly sorrowful language. His entry belongs to a fortune-telling tradition that often attached harsh forecasts to cards. A history page can record that fact without carrying those predictions into the present as reliable information. The modern association with anxious thoughts is a way of responding to the scene, not a medical diagnosis and not proof that the pictured trouble will occur. Its emotional force is clearer than any factual forecast.', '韦特描写一个坐起哀叹的人，并使用非常悲伤的语言。他的条目属于常把严厉预言附加在纸牌上的占卜传统。历史介绍可以记录这一点，却不必把旧预言当成今天可靠的信息。现代关于忧虑念头的理解，是对场景的一种回应，不是医学诊断，也不能证明图中的灾难会发生。它的情绪力量，比任何事实预报都更明确。'],
    scene: ['The person’s hands cover their face, leaving the viewer with posture instead of expression. Nine horizontal swords stretch across a dark background, above a patterned bedcover. Unlike the Ten, the blades do not pierce the body. Smith has placed suffering in an interior room, where thought, memory, and imagination can feel overwhelmingly present. The familiar shelter of a bed makes that distress intimate: the problem has entered the place where someone might normally expect to rest.', '人物用双手遮住脸，我们看到的是姿态而非表情。九把横剑铺在黑色背景上，下方是有图案的床被。不同于宝剑十，这些剑没有穿透身体。史密斯把痛苦放进室内，在那里，思绪、记忆和想象都可能显得格外逼近。床本应是休息之处，熟悉的庇护因此让痛苦更私密：困扰进入了人们原本期待放松的地方。'],
    symbols: [
      [['Covered face', '遮住的脸'], ['The gesture communicates distress without naming its cause. It keeps the scene emotionally clear while leaving the person’s circumstances unknown.', '这个动作清楚表达痛苦，却不说明原因；情绪鲜明，个人处境仍未被揭示。']],
      [['Suspended swords', '悬置的剑'], ['The blades remain above the figure. Their threatening presence is distinct from a depicted injury, an important visual difference from the Ten.', '剑停留在人物上方。威胁的存在与实际描绘的伤害不同，这是它和宝剑十的重要视觉区别。']],
      [['Patterned cover', '有图案的被子'], ['The detailed fabric introduces ordinary domestic care into the dark scene. Life contains more texture than the overwhelming moment alone suggests.', '细致布料把日常生活的照料带入黑暗场景，提醒我们生活比压倒人的一刻更丰富。']],
    ],
    reflection: ['Used gently, the picture can make space for saying that something feels heavy, especially when it is hard to explain. It need not be turned into an instruction to think harder or solve everything alone. Asking what would make the next hour more bearable may be more useful than treating the scene as a verdict on the future. Its history shows how the same image can move from alarming prediction toward a language of recognition, company, and support.', '温和地使用这幅图，可以帮助人承认某件事很沉重，尤其是在难以解释的时候。它不应变成要求人想得更多、独自解决一切的命令。问下一小时怎样能好过一点，可能比把图像当成未来判决更有帮助。它的历史也展示了，同一幅画如何从令人害怕的预言，转向承认感受、陪伴与支持的语言。'],
    detail: ['The swords do not enter the body. That visible distinction helps separate the experience of dread from evidence that a feared event has happened.', '剑没有刺入身体。这个可见区别有助于分清恐惧的体验，与所怕之事已经发生的证据。'],
  },
  {
    id: 'swords-10',
    teaser: ['The darkest Sword scene contains a surprising historical caution: it is not specifically a prediction of violent death.', '最黑暗的宝剑画面，竟伴随一项明确提醒：它并非专门预言暴力死亡。'],
    past: ['Waite describes the fallen figure and the full set of ten piercing swords, then expressly rejects treating the card as especially about violent death. That sentence matters because the dramatic illustration can invite literal fear. His recorded meanings concern pain, sadness, and desolation more broadly. The history of the accompanying text therefore provides a limit on sensational interpretation: even its original commentator did not reduce this image to a straightforward forecast of physical catastrophe.', '韦特描写倒下的人与十把刺入的剑，随后明确表示，这张牌并不特别指向暴力死亡。这个句子很重要，因为戏剧化图像容易引起字面上的恐惧。他记录的含义更广泛地涉及痛苦、悲伤与荒凉。因此，配套文字的历史也为耸动解释划出界限：即使最初的评论者，也没有把它简化为身体灾难的直接预报。'],
    scene: ['Smith places the body in the foreground, with a dark sky above and a narrow band of light over distant water. The ten swords make the event visually excessive, far beyond what a realistic account would require. That excess can be read as an emblem of total defeat rather than a documentary scene. Meanwhile, the horizon prevents blackness from filling the whole card. The picture holds a severe ending and a world beyond that ending in the same frame.', '史密斯把身体放在前景，上方是黑暗天空，远方水面上留着一条光带。十把剑使事件在视觉上过度强烈，远超现实叙事所需。这种夸张可以被看作彻底失败的徽记，而不是纪实场面。地平线又使黑暗没有占满整张牌。严厉的结束与结束之外仍存在的世界，被放在同一个画框中。'],
    symbols: [
      [['Ten swords', '十把剑'], ['The entire numerical sequence accumulates on one figure. The extreme quantity makes the image feel final and emblematic rather than casually realistic.', '整个数字序列积聚在一个人身上，极端数量使图像显得终结且象征化，而不是平常的写实。']],
      [['Dark sky', '黑暗天空'], ['Darkness dominates the upper picture and intensifies the sense of collapse. It establishes atmosphere without specifying how long that condition will last.', '黑暗占据上部画面，增强崩塌感。它建立氛围，却没有说明这种状态会持续多久。']],
      [['Light at the horizon', '地平线的光'], ['The visible light gives later readers a foothold for renewal. It is a pictorial opening, not a timetable or guarantee of rapid recovery.', '可见的光为后世读者提供重新开始的入口，但它不是恢复时间表，也不保证迅速好转。']],
    ],
    reflection: ['A reflective reading can ask what truly has finished and what is being made to feel total by the intensity of the moment. Sometimes a failed plan is only a failed plan, even when it seems to define everything. The image can acknowledge the seriousness of an ending while allowing practical care and a new perspective to develop gradually. Its historical caution is useful: powerful visual language should not be mistaken for evidence of an inevitable event.', '反思时可以问：究竟什么结束了，什么只是因为当下感受太强而显得全盘终结？有时，一个失败计划仍只是一个失败计划，尽管它似乎定义了全部生活。图像可以承认结束的严肃，同时容许实际照料与新视角慢慢出现。历史文字的提醒很有价值：强烈的视觉语言，不应被误认为不可避免事件的证据。'],
    detail: ['Waite specifically warns against making violent death the card’s special meaning. This qualification belongs beside the illustration, not hidden from it.', '韦特特别否定把暴力死亡当成这张牌的专属含义。这个限定应与图像并列呈现，而不是被藏起来。'],
  },
  {
    id: 'swords-11',
    teaser: ['A watchful young figure turns the court’s messenger into a study of attention, questions, and suspicion.', '警觉的年轻人物，把宫廷信使变成关于观察、提问与怀疑的研究。'],
    past: ['The Page inherits a court-card role rather than a numbered arrangement of weapons. Pages and knaves helped populate the miniature social world of a deck. In Waite’s account, this particular Page is alert to a possible enemy and belongs to the territory of watching, examining, and gathering information. Modern language about curiosity and learning develops one side of that vigilance, while the older description also leaves room for intrusive observation and suspicion.', '侍从继承的是宫廷角色，而不是武器数量的排列。侍从或侍者组成纸牌中的微型社会。韦特笔下，这位侍从警惕可能出现的敌人，与观察、检查和搜集信息有关。现代关于好奇与学习的说法，发展了这种警觉的一面；旧描述也保留了侵入式观察与怀疑的可能。'],
    scene: ['Smith’s Page stands on uneven ground with both hands on a raised sword. The head turns away from the direction of the body, creating a feeling of readiness for something not yet seen. Clouds and wind give the scene energy without depicting an actual battle. The figure looks capable but not settled. Compared with the stationary rulers of the suit, this court member appears to be discovering the surrounding world moment by moment.', '史密斯的侍从站在不平地面上，双手握住举起的剑。头部转向与身体不同的方向，仿佛准备应对尚未看见的事物。云与风带来能量，却没有真正的战斗。人物看起来有能力，但尚未安定。与花色中静坐的统治者相比，这位宫廷成员像是在一刻一刻地认识周围世界。'],
    symbols: [
      [['Two-handed grip', '双手握剑'], ['Both hands engage the weapon, making effort and readiness visible. A contemporary reading can connect this with learning to handle a demanding tool.', '双手都参与持剑，努力与准备清楚可见。现代阅读可以把它联系到学习掌握一项不易使用的工具。']],
      [['Turning head', '转动的头'], ['The figure attends to more than one direction. That can be alert curiosity, but the posture can also suggest the strain of constant checking.', '人物同时留意不止一个方向，可以是敏锐的好奇，也可能暗示不断检查带来的紧绷。']],
      [['Uneven ground', '不平的地面'], ['The landscape asks the Page to remain adaptable. It makes the court role active and exposed rather than sheltered inside a palace.', '地形要求侍从保持灵活，让宫廷角色显得活跃且暴露在外，而非安居宫中。']],
    ],
    reflection: ['The useful question is not simply whether to be more alert, but what kind of attention serves the situation. Curiosity can test an assumption and invite a better explanation; suspicion can keep collecting details without ever allowing reassurance. The card offers an image for learning that difference. Court cards need not identify a person of a fixed age or gender: here the role can be a mode of thinking that anyone adopts when entering unfamiliar territory.', '值得问的不只是要不要更加警觉，而是哪种注意力真正有帮助。好奇能够检验假设、邀请更好的解释；怀疑则可能不断搜集细节，却永远不允许安心。这张牌提供了学习区分两者的图像。宫廷牌不必指定固定年龄或性别的人：这里的角色可以是任何人进入陌生领域时采用的一种思考方式。'],
    detail: ['Waite’s Page is closer to an observer or examiner than a classroom student. The modern “learning” theme softens, but does not exhaust, that watchfulness.', '韦特的侍从更接近观察者或检查者，而非课堂学生。现代的“学习”主题柔化了警觉，却没有穷尽它。'],
  },
  {
    id: 'swords-12',
    teaser: ['The charging knight carries the speed of a heroic romance—and the risk of outrunning judgment.', '疾驰骑士带着英雄传奇的速度，也带着行动快过判断的风险。'],
    past: ['Waite explicitly compares this Knight with the ideal hero of chivalric romance, even suggesting Galahad as a likeness. That is a literary comparison in the handbook, not proof that Smith depicted a particular episode from an Arthurian story. His meanings range from bravery and skill to anger and destruction. The card’s inherited mounted rank becomes a way to explore the ambiguous force of heroic action: courage can protect, but conviction alone cannot settle whether a cause is wise.', '韦特明确把这位骑士与骑士文学中的理想英雄相比，甚至提及加拉哈德。这是说明书里的文学类比，并不能证明史密斯描绘了亚瑟王故事中的某一幕。他列出的含义从勇敢、技巧延伸到愤怒与破坏。传统的骑乘等级因此成为讨论英雄行动复杂力量的方式：勇气能够保护人，但仅凭信念并不能证明事业明智。'],
    scene: ['The horse stretches forward and the rider leans into the charge with sword raised. Trees and clouds appear swept by wind, reinforcing the direction and pace. Smith gives little space for hesitation; the whole composition seems to move beyond its border. Unlike the Pentacles Knight’s patient stillness, this scene compresses intention into immediate action. We see commitment clearly, but the destination and the people affected by the charge remain outside the frame.', '马向前伸展，骑士俯身冲刺，高举宝剑。树与云仿佛被风推向一侧，强化方向和速度。史密斯几乎没有给犹豫留下空间，整幅画像要冲出边框。与星币骑士的耐心静止不同，这里把意图压缩成立即行动。承诺十分清楚，目的地以及冲锋会影响的人，却都在画面之外。'],
    symbols: [
      [['Charging horse', '冲锋的马'], ['The horse carries momentum through the entire picture. Speed is a visible fact here; whether that speed is useful remains an interpretive question.', '马把动势贯穿全图。速度是可见事实，但速度是否有用，仍是需要解释的问题。']],
      [['Raised sword', '高举的剑'], ['The blade presents an intention to act rather than negotiate. It can suggest defence or aggression depending on the wider context of a reading.', '剑展现行动而非协商的意图。结合更广泛的情境，它既可能指保护，也可能指攻击。']],
      [['Wind-shaped landscape', '受风影响的风景'], ['The weather repeats the rider’s urgency. It makes the charge feel like part of an atmosphere, not merely one isolated movement.', '天气重复骑士的急迫，让冲锋像整个环境的状态，而非单独的一次动作。']],
    ],
    reflection: ['A contemporary reading can ask whether rapid action is answering a genuine need or merely the discomfort of waiting. There are moments when quick defence matters, and moments when a question would help more than a charge. The card’s literary ancestry makes that tension vivid: heroic stories celebrate courage, yet readers still need to ask whom the hero serves. Keeping the unseen destination in mind prevents energy and certainty from being mistaken for a complete plan.', '现代阅读可以问：迅速行动是在回应真实需要，还是只为摆脱等待的不适？有些时候及时保护很重要，有些时候提一个问题比冲锋更有效。文学联想使张力更鲜明：英雄故事赞美勇气，但仍要问英雄为谁服务。记住画外尚未看见的目的地，就能避免把能量和确定感当成完整计划。'],
    detail: ['Galahad appears as Waite’s comparison, not as an identified subject of the artwork. The distinction keeps literary association separate from documented commission history.', '加拉哈德是韦特的类比，而非被证实的画中人物。这一区别把文学联想与明确的创作委托历史分开。'],
  },
  {
    id: 'swords-13',
    teaser: ['An upright blade and an open hand make a portrait more complex than the stereotype of a cold queen.', '竖直的剑与张开的手，让王后的肖像超越冷酷的刻板印象。'],
    past: ['Queens already belonged to historical tarot courts; Smith did not invent the female ruler as a card rank. What changes here is the particular emotional portrait. Waite describes a severe face shaped by sorrow and records meanings closely tied to the gender assumptions of his period. Modern readings often emphasize independence, discernment, and direct speech instead. That shift is part of the card’s reception history, not proof that one timeless personality description has remained unchanged.', '王后早已属于历史塔罗的宫廷成员，史密斯并没有发明女性统治者这一牌阶。这里变化的是具体的情绪肖像。韦特描述经历悲伤后的严肃面容，并记录了与其时代性别观念密切相关的含义。现代阅读常转而强调独立、辨别力与直言。这种变化属于牌的接受历史，不能证明某个永恒的人格描述从未改变。'],
    scene: ['The Queen sits in profile, lifting a sword vertically while extending her other hand. The composition combines a clear boundary with an outward gesture. Her throne and garments carry decorative detail, but the face and blade remain the strongest lines of attention. Smith does not show a conversation partner, so the open hand may be invitation, acknowledgment, or command. The image holds distance and engagement together rather than requiring the Queen to be either entirely welcoming or entirely closed.', '王后侧身而坐，一手竖直举剑，另一只手向外伸出。构图同时包含清晰界限与朝外的动作。宝座和衣饰虽然细致，面孔与剑仍是最强的视觉方向。史密斯没有画出谈话对象，因此张手可以是邀请、回应或命令。图像把距离与参与放在一起，并不要求王后完全欢迎别人，或完全封闭。'],
    symbols: [
      [['Vertical blade', '竖直的剑'], ['The upright sword gives the portrait precision and resolve. Its stillness distinguishes considered authority from the Knight’s immediate charge.', '直剑赋予肖像精确与决心。它的静止也区分了经过思考的权威与骑士的立即冲锋。']],
      [['Open hand', '张开的手'], ['The free hand reaches beyond the throne. This visible openness complicates a reading that reduces the Queen to rejection or emotional coldness.', '空着的手伸向宝座之外，这种可见的开放使“拒绝”或“冷漠”的单一解释显得不足。']],
      [['Profile', '侧面姿态'], ['The sideways view directs attention outward rather than straight at the viewer. It suggests a relationship to something beyond the frame without naming it.', '侧面把注意力引向外部，而不是直接面对观者；它暗示与画外事物的关系，却没有指明对象。']],
    ],
    reflection: ['For reflection, the Queen can represent the ability to speak accurately after experience has made easy answers less convincing. That does not require becoming unkind. One can be clear about a limit while remaining interested in another person’s account. Reading the historical text critically also matters: a person’s gender, appearance, or relationship status does not determine their character. The enduring visual question is how to combine a steady standard with an open hand.', '用于反思，王后可以代表经历使简单答案不再令人信服之后，仍能准确表达的能力。这并不要求变得刻薄。一个人可以清楚表达界限，同时愿意听另一人的解释。批判性地阅读旧文本也很重要：性别、外貌或关系状态不能决定品格。图像持续提出的问题是，如何把稳定标准与开放的手结合起来。'],
    detail: ['The open hand is as important as the sword. Looking at both prevents an inherited stereotype from replacing what the artist actually drew.', '张开的手与宝剑同样重要。同时看见两者，才能避免让继承来的刻板印象取代艺术家实际画出的内容。'],
  },
  {
    id: 'swords-14',
    teaser: ['This king holds a judge’s weapon, raising the question of what makes authority worthy of trust.', '国王握着如同裁判者的武器，追问什么使权威值得信任。'],
    past: ['The King’s rank comes from the established court structure, where sovereignty was immediately recognizable. Waite connects this Sword ruler with judgment, command, law, and official authority. He also compares him with Justice, while distinguishing the power of an office from the virtue itself. That is a useful historical nuance: possessing authority is not the same thing as embodying fairness. The card’s meaning develops through the relationship between a person, a weapon, and a recognized position.', '国王的等级来自已有的宫廷结构，主权在其中一眼可辨。韦特把宝剑国王与判断、命令、法律及官方权威相连。他还将其与正义牌比较，同时区分职位拥有的力量与正义这一美德。这是很有价值的细节：拥有权威，不等于体现公平。牌的意义通过人物、武器和被认可的职位之间的关系发展。'],
    scene: ['Smith seats the King frontally, with the sword lifted and the body firmly supported by a decorated throne. The direct arrangement makes him feel present and answerable, unlike a figure glimpsed in movement. Clouds and distant landscape keep him within a world beyond the seat of power. The blade is not being swung, but its availability is unmistakable. This is authority held in reserve, which can protect order or make its misuse especially consequential.', '史密斯让国王正面坐着，举起宝剑，身体由装饰宝座稳定承托。直接的构图使他显得在场、需要作出回应，不同于移动中一闪而过的人物。云和远景也让权力座位之外的世界仍然存在。剑没有挥出，但随时能够使用。这是被保留的权威：它可以保护秩序，也让滥用造成的后果格外重大。'],
    symbols: [
      [['Frontal throne', '正面的宝座'], ['The seat gives the figure stability and status. It also invites scrutiny: a position of judgment should be able to face those affected by it.', '座位给予稳定和地位，也邀请审视：作出判断的位置，应能面对受其影响的人。']],
      [['Unsheathed sword', '出鞘的剑'], ['The weapon is visible even in stillness. Waite treats it as part of the ruler’s power of office, not simply an ornament of intelligence.', '即使静止，武器也清楚可见。韦特把它视为职位力量的一部分，而非仅仅装饰性的聪明象征。']],
      [['Open surroundings', '开阔环境'], ['The King does not occupy a sealed chamber. The visible world beyond the throne helps a reflective reading connect decisions with their wider consequences.', '国王并不位于密闭房间。宝座之外可见的世界，可以帮助我们把决定与更广泛的后果联系起来。']],
    ],
    reflection: ['Today the card can prompt a careful standard for decisions: distinguish facts from preferences, explain the reasoning, and remain accountable for consequences. These are contemporary applications of its judicial imagery, not claims that historical kings always behaved that way. The comparison with Justice also encourages humility. A rule can be applied confidently and still deserve revision. The strongest version of this role combines intellectual clarity with the willingness to hear information that challenges its own judgment.', '今天，这张牌可以提示认真决策的标准：区分事实与偏好，说明理由，并为后果负责。这些是司法图像的现代应用，并不意味着历史君主一直如此。与正义牌的比较也鼓励谦逊：一项规则可以被自信执行，同时仍值得修订。这个角色最有力的一面，是把清晰思考与愿意听取挑战自身判断的信息结合起来。'],
    detail: ['Waite distinguishes the power of an office from Justice as a virtue. That gap is the most interesting question behind this apparently certain ruler.', '韦特区分了职位的权力与正义的美德。两者之间的距离，正是这位看似确定的统治者背后最有趣的问题。'],
  },
  {
    id: 'pentacles-01',
    teaser: ['A single star-marked coin appears above a garden, making prosperity look like an invitation rather than a trophy.', '一枚带星的钱币出现在花园上方，让富足像一份邀请，而不是奖杯。'],
    past: ['The Ace presents the suit’s emblem by itself, making the change from coin to pentacle especially easy to see. Waite associates it with contentment and comfortable material conditions, while also asking whether wealth benefits its possessor. That second thought complicates a simple promise of money. The historical entry makes possession and wellbeing related but not identical: something can be valuable without automatically making a life good, and prosperity still calls for interpretation.', '王牌单独呈现花色标志，使钱币转为星币的变化格外清楚。韦特把它与满足及舒适的物质条件相连，同时追问财富是否真正有益于拥有者。后一个问题使“将有钱来”的简单许诺变得复杂。旧条目把占有与幸福联系起来，却没有把它们等同：事物可以有价值，却不会自动使生活美好；富足仍需要理解。'],
    scene: ['Smith places the offered pentacle above a flowering garden. A path leads through a leafy arch toward distant hills, so the picture contains both a sheltered present and a world to enter. The hand supports the disc rather than gripping it defensively. Compared with the Four’s tightly held possessions, this emblem looks available. The scene does not show anyone accepting it or completing the journey; opportunity remains a beginning with an open future.', '史密斯把被托起的星币放在开花的花园上方。一条路穿过绿叶拱门通向远山，画面因此同时包含受到庇护的当下与可以进入的世界。手托着圆盘，没有防御性地紧抓。与星币四紧抱财物相比，这个标志显得可以接近。图上没有人接下它，也没有人走完旅程；机会仍只是面向开放未来的开始。'],
    symbols: [
      [['Open palm', '张开的手掌'], ['The hand supports rather than clutches the disc. That difference makes the object appear offered, allowing a reading of possibility rather than ownership alone.', '手托住而非紧抓圆盘，使物品像是被提供出来，因而可以读作可能性，而不只是所有权。']],
      [['Garden path', '花园小径'], ['The path links the foreground with the arch. It gives the material emblem a setting of movement and development rather than a sealed treasure chamber.', '小径把前景与拱门相连，让物质标志处在移动与发展的环境中，而不是封闭的藏宝室。']],
      [['Distant heights', '远处高地'], ['The landscape beyond the garden keeps effort in view. A promising beginning need not mean that every later step will be easy.', '花园之外的远景让努力仍然可见。良好开端，并不表示以后每一步都会轻松。']],
    ],
    reflection: ['For reflection, the Ace can make an opportunity concrete: a tool, a little time, a manageable resource, or a skill that can be practised. The garden suggests that conditions matter as much as wishing. What would help a useful beginning take root? That is a modern application of the picture, not a guarantee of financial gain. Waite’s distinction between wealth and benefit also asks whether the opportunity supports the life someone actually wants.', '反思时，王牌可以让机会变得具体：一件工具、一点时间、可掌握的资源，或能够练习的技能。花园暗示，条件与愿望同样重要。什么能使一个有用的开始扎根？这是图像的现代应用，不是获利保证。韦特区分财富与益处，也让人追问机会是否支持自己真正想过的生活。'],
    detail: ['Waite allows prosperity to be present while questioning its benefit. This Ace is richer than an automatic “yes” to every material opportunity.', '韦特容许富足存在，同时质疑它的益处。因此这张王牌并非对所有物质机会自动说“好”。'],
  },
  {
    id: 'pentacles-02',
    teaser: ['A dancer keeps two coins moving while ships rise and fall behind him: balance becomes a rhythm.', '舞者让两枚钱币持续流转，身后的船随浪升降：平衡变成一种节奏。'],
    past: ['Waite describes the figure as dancing, not explicitly as an accountant or a worker juggling deadlines. His meanings range from gaiety to agitation and written messages. The familiar modern idea of balancing responsibilities therefore develops the movement in the design rather than reproducing one fixed historical definition. The pair of coins remains connected, so the image can concern exchange and adjustment as well as choosing between separate alternatives. The written tradition is more varied than a single productivity lesson.', '韦特把人物描述为正在跳舞，并没有明确说他是会计或赶期限的工作者。他列出的含义从欢乐延伸到不安和书面消息。现代常见的平衡责任，是对画面运动的发展，而非复制一个固定的历史定义。两枚钱币始终相连，因此图像既能关乎交换与调整，也能关乎选项之间的选择。文字传统比一堂效率课程更丰富。'],
    scene: ['Smith puts the figure on one foot with a pentacle in each hand. An endless loop joins the discs, while two ships negotiate exaggerated waves in the distance. The body’s small-scale movement echoes the sea’s larger rhythm. This doubling makes the card playful but not completely relaxed: balance is being continually remade. The figure does not sit on secure possessions like the Four; he handles them through an ongoing act of attention.', '史密斯让人物单脚站立，双手各持一枚星币。没有终点的环带连接圆盘，远处两条船则面对起伏夸张的海浪。身体的小动作呼应海洋的大节奏，使牌既顽皮又不完全放松：平衡需要不断重新建立。人物不像星币四那样坐在稳固财物上，而是通过持续注意来处理它们。'],
    symbols: [
      [['Endless loop', '无尽环带'], ['Waite notices the sideways-eight shape joining the coins. It makes their relationship continuous, though no single universal meaning for the loop is supplied.', '韦特注意到连接钱币的横向八字形。它使关系持续不断，却没有为环带指定唯一普遍含义。']],
      [['Raised foot', '抬起的脚'], ['The stance makes balance active rather than static. It suggests adjustment in motion, not the achievement of a position that will never change.', '姿态使平衡成为动态，而非静态；它提示运动中的调整，不是找到一个永远不变的位置。']],
      [['Ships and waves', '船与浪'], ['The background repeats the theme on a larger scale. Changing conditions continue whether or not the foreground figure can control them.', '背景在更大尺度上重复主题。条件持续变化，并不取决于前景人物能否控制它们。']],
    ],
    reflection: ['The card can encourage flexibility without celebrating endless busyness. A rhythm is useful only if a person can sustain it. Which demand can move, which needs a firmer place, and what happens when the waves grow? Those are contemporary questions drawn from the scene. Waite’s inclusion of enjoyment also deserves attention: not every complex situation is miserable. There can be skill and play in managing change, provided that motion does not become an obligation to perform cheerfulness.', '这张牌可以鼓励灵活，却不必赞美无休止的忙碌。节奏只有在人能够维持时才有用。哪个要求可以移动，哪个需要更稳定的位置，浪变大时怎么办？这些都是从场景提出的现代问题。韦特包含快乐这一点也值得注意：复杂处境未必全然痛苦。应对变化可以有技巧和游戏感，只要运动没有变成必须表现愉快的义务。'],
    detail: ['The original description calls this a dance. Reading only workload misses the deliberate playfulness that gives the card its distinctive energy.', '原描述称这是一场舞蹈。若只想到工作量，就会遗漏这张牌独特能量中的游戏感。'],
  },
  {
    id: 'pentacles-03',
    teaser: ['A craftsperson meets two listeners beneath a stone arch: skill becomes visible through a shared project.', '工匠在石拱下与两位聆听者相遇：技艺通过共同项目变得可见。'],
    past: ['Waite identifies a sculptor working in a monastery and explicitly compares this card with the Eight of Pentacles. In his explanation, the apprentice associated with the Eight has advanced to serious recognized work here. This is a striking reminder that the numbered cards do not necessarily tell a simple story from one to ten. The Three can represent a later professional stage than the Eight. Its history is about craft and recognition, not merely the mystical properties of a number.', '韦特把人物称为在修道院工作的雕刻师，并明确与星币八比较。在他的解释中，星币八所关联的学徒在这里已经进入受到认可的正式工作。这提醒我们，数字牌未必按一至十讲述简单的成长顺序。星币三可以比星币八代表更晚的职业阶段。它的故事关乎技艺与认可，而不只是数字的神秘属性。'],
    scene: ['Smith places the worker on a low support beneath the carved architecture. Two other figures attend, one holding a plan or document. The pentacles are integrated into the building rather than piled up as spending money. Hands, faces, and the drawn design create a visual exchange between practical making and discussion. The identities of the visitors should not be over-specified, but their attention makes clear that the work belongs within a larger undertaking.', '史密斯让工匠站在低台上，头顶是雕刻建筑。另两人参与其中，一位拿着图纸或文书。星币融入建筑，而不是堆成可花的钱。手势、面孔与图样在制作和讨论之间建立视觉交流。来访者的身份不宜被过度确定，但他们的关注表明，这份工作属于更大的共同事业。'],
    symbols: [
      [['Carved arch', '雕刻的拱门'], ['The coins become architectural decoration. Value appears as something made and incorporated into a durable structure, not just possessed privately.', '钱币成为建筑装饰，价值体现为制作并融入持久结构的东西，而不只是私人占有物。']],
      [['Raised worker', '站在台上的工匠'], ['The craftsperson occupies the place where the work happens. The arrangement gives skilled hands a visible authority within the conversation.', '工匠占据实际工作的位置，这种安排让熟练的双手在谈话中拥有可见的权威。']],
      [['Document', '图纸或文书'], ['The held sheet connects intention with execution. A modern reading can see coordination here, while avoiding unsupported claims about the visitors’ exact professions.', '纸张把意图与执行相连。现代阅读可以看见协调，却不必对来者的准确职业作无依据判断。']],
    ],
    reflection: ['The scene can prompt questions about how expertise is noticed and how people work together. Does the person doing the practical work have a voice in planning? Are expectations clear enough for skill to become a good result? These are contemporary applications of the image’s collaboration. Waite’s comparison with the Eight also offers encouragement: practice and recognition are related, but not identical. Becoming capable is one process; finding a setting that values capability is another.', '场景可以促使我们思考专业能力如何被看见，以及人们怎样合作。实际执行的人能参与规划吗？要求是否足够清晰，能让技艺转为好成果？这些是协作图像的现代应用。韦特与星币八的对照也带来启发：练习与认可彼此相关，却不相同。培养能力是一回事，找到珍惜能力的环境是另一回事。'],
    detail: ['Waite makes the Three’s worker more advanced than the Eight’s apprentice. The suit’s numbers are not a compulsory chronological career ladder.', '韦特认为星币三的工匠比星币八的学徒更成熟。因此花色数字并不是必须按时间排列的职业阶梯。'],
  },
  {
    id: 'pentacles-04',
    teaser: ['A crowned figure has secured every coin—but keeping them still has also made his body still.', '戴冠的人守住了每枚钱币，但让钱币不动，也让自己的身体动不了。'],
    past: ['Waite describes holding firmly to what one possesses, and includes security, gifts, and inheritance among the meanings. The historical entry is not simply a condemnation of greed. A stable store of resources can protect a person, and an inheritance can connect possession with continuity. Smith’s picture nevertheless gives that security a bodily cost. The interesting development is the tension between a defensible need for safety and the restrictive posture required to keep everything under control.', '韦特描述紧守已有之物，并把安全、礼物与继承列为含义。因此旧条目并非单纯谴责贪婪。稳定资源可以保护人，继承也能使占有与延续相连。然而史密斯的画面让这种安全付出身体代价。值得关注的是两者的张力：一方面是合理的安全需要，另一方面是为了控制一切而采取的受限姿态。'],
    scene: ['One pentacle sits above the figure’s crown, one is held against the torso, and two lie beneath the feet. A town spreads behind the seated figure. The whole arrangement is remarkably compact: head, arms, and feet all participate in securing the objects. There is little spare movement. Unlike the Two’s lively circulation, value here is pinned into position. The distant town suggests a social world, while the foreground remains absorbed in keeping possessions close.', '一枚星币在王冠上，一枚抱在胸前，两枚压在脚下。城镇在坐着的人身后展开。整个排列非常紧凑：头、双臂和双脚都参与守住物品，几乎没有剩余动作空间。与星币二的活跃流转不同，这里的价值被固定住。远处城镇暗示社会生活，前景却专注于把所有物保持在身边。'],
    symbols: [
      [['Coin against the chest', '胸前的钱币'], ['The central disc is enclosed by both arms. The gesture can be protective or possessive, depending on what the person needs and fears.', '中央圆盘被双臂围住。这个动作可以是保护，也可以是占有，要看人物的需要与恐惧。']],
      [['Coins underfoot', '脚下的钱币'], ['The feet secure two more discs, limiting freedom of movement. The image turns a financial idea into a physical arrangement that the viewer can feel.', '双脚守住另外两枚圆盘，也限制了移动自由。图像把财务概念变成人能够感受到的身体安排。']],
      [['Town behind', '身后的城镇'], ['The inhabited background offers life beyond the held objects. It makes the contrast between individual security and wider participation visible.', '有人居住的背景提供财物之外的生活，使个人安全与参与更广阔世界的对照可见。']],
    ],
    reflection: ['A useful reading avoids shaming someone for needing stability. Instead, it asks whether a particular safeguard still serves its purpose. Does holding tightly protect what matters, or prevent the resource from being used at all? The same question can apply to time, knowledge, affection, or money. That broader application extends the visual metaphor; it does not erase the older concern with actual possessions. The card is most interesting where protection and restriction become difficult to separate.', '有用的阅读不应羞辱一个人对稳定的需要，而应问某项防护是否仍在发挥作用。抓紧是在保护重要之物，还是让资源根本无法使用？同样的问题可以涉及时间、知识、感情或金钱。这种扩展来自视觉比喻，并没有抹去旧解释对实际财物的关注。当保护与限制变得难以分开时，这张牌最有意思。'],
    detail: ['Every limb has a guarding job. The composition makes the cost of control visible before any interpretation calls the figure generous or greedy.', '每个肢体都有看守任务。还未把人物说成慷慨或贪心，构图就已经让控制的代价可见。'],
  },
  {
    id: 'pentacles-05',
    teaser: ['Two people pass a glowing window in the snow: the story is about exclusion as much as lack.', '两个人在雪中走过发亮的窗：故事不只关乎匮乏，也关乎被隔在外面。'],
    past: ['Waite emphasizes material hardship, then records a sharply different tradition connecting the card with affection and companionship. He openly says these meanings cannot be reconciled easily. That historical disagreement matters. The picture can show people in need and people travelling together at once. Neither observation establishes a complete explanation for their situation. Treating the card only as a bad financial omen loses both the human relationship in the image and the uncertainty acknowledged by its early commentator.', '韦特强调物质困苦，随后又记录了把牌与感情和陪伴联系起来的另一种传统，并坦言这些意义不容易协调。这个历史分歧很重要。图像可以同时呈现需要帮助的人，以及一起前行的人。任何一项观察都无法完整解释他们的处境。若只把它当作坏财运征兆，就会遗漏画面中的人际关系与早期评论者承认的不确定。'],
    scene: ['Smith places two poorly protected figures in falling snow. One uses crutches. Above them, five pentacles glow inside a stained-glass window, so the suit’s objects are visible but inaccessible within the immediate scene. We do not see a doorway, an invitation, or a refusal. The contrast is therefore stronger than a tidy moral: warmth and value exist nearby, yet the people remain outside. Their hardship is presented in relation to a built social environment.', '史密斯让两个衣着不足以御寒的人走在雪中，其中一人使用拐杖。上方彩色玻璃窗里，五枚星币发光，使花色物件清楚可见，却在眼前场景中不可触及。我们没有看见门、邀请或拒绝。因此，对照比一个整齐的道德结论更强：温暖与价值就在附近，人却仍在外面。困境被放在有人建造的社会环境之中。'],
    symbols: [
      [['Lit window', '发亮的窗'], ['The window places visible abundance beside exposure. It does not prove that help is readily available or that the figures have chosen to refuse it.', '窗把可见的富足与暴露并置，却不能证明帮助随手可得，更不能证明人物主动拒绝了帮助。']],
      [['Crutches', '拐杖'], ['The support makes a practical difficulty visible. A considerate reading notices access and assistance rather than turning hardship into a character judgment.', '辅助器具让实际困难可见。体贴的阅读会关注可及性与援助，而不是把困苦变成人格评价。']],
      [['Two travellers', '两个同行者'], ['The figures share the same weather and direction. Their companionship can matter without magically cancelling material need.', '两人共享天气与方向。陪伴可以重要，却不会神奇地消除物质需要。']],
    ],
    reflection: ['The image can support a grounded question about support: what is missing, who can help, and what barriers make help difficult to reach? It should not become an instruction to blame someone for feeling excluded. Nor does a warm-looking building prove that the people outside simply failed to notice an open door. The historical contradiction between hardship and attachment allows a gentler insight: connection can survive difficulty, while practical needs still deserve a practical response.', '图像可以支持关于援助的具体提问：缺少什么，谁能帮忙，哪些障碍使帮助难以获得？它不应变成责怪被排斥者的指令。看似温暖的建筑，也不能证明外面的人只是没注意到敞开的门。旧解释中困苦与依恋的冲突，容许一种更温和的理解：关系能够在困难中延续，而实际需要仍值得实际回应。'],
    detail: ['No open door is visible. The common story that help is available if the figures would only look is an interpretation, not a depicted fact.', '画面没有可见的敞开门。“只要他们留意就能得到帮助”是解释，不是被画出的事实。'],
  },
  {
    id: 'pentacles-06',
    teaser: ['A giver holds scales above two waiting people: generosity and power occupy the same small scene.', '施予者拿着秤，面前两人等待：慷慨与权力占据同一个小场景。'],
    past: ['Waite calls the central figure a merchant who distributes money to people in need. He reads the action as evidence of success and goodwill. The older coin suit becomes a direct picture of giving rather than an abstract emblem of wealth. A modern viewer may also notice unequal positions and the giver’s control over distribution. That is a critical reading of the visible arrangement, not a claim that Waite himself supplied a detailed analysis of charity or social power.', '韦特称中央人物为商人，把钱分给有需要的人，并把行动看作成功与善意的证明。旧钱币花色在这里变成直接的施予场景，而不是抽象财富符号。现代观者也可能注意位置的不平等，以及施予者掌握分配的权力。这是对可见安排的批判性阅读，并不意味着韦特本人已经提出完整的慈善或社会权力分析。'],
    scene: ['The standing figure holds scales in one hand and releases coins with the other. Two kneeling people extend their hands, but the visible giving is directed toward one of them. Six pentacles float above the group, separating the emblematic count from the small coins in the transaction. Smith makes generosity legible through action, while the contrasting postures keep dependence visible. The scene is therefore both an exchange of resources and a composition of unequal heights.', '站立人物一手持秤，另一手放下钱币。两位跪着的人伸出双手，但可见的施予朝向其中一人。六枚星币浮在群体上方，把象征性的计数与交易中的小钱分开。史密斯通过动作使慷慨容易辨认，也通过不同姿态保留依赖关系。因此，这既是资源交换，也是高度不平等的构图。'],
    symbols: [
      [['Scales', '秤'], ['The scales introduce measurement and judgment. They can suggest fairness, but their presence alone does not establish that everyone receives what they need.', '秤引入衡量与判断，可以提示公平，但它的出现并不能证明每个人都得到所需。']],
      [['Giving hand', '施予的手'], ['The action turns stored wealth into circulation. It gives the suit a social relationship rather than keeping value entirely inside one person’s possession.', '动作让积存财富进入流通，使花色具有社会关系，而不把价值完全锁在一个人的占有中。']],
      [['Unequal postures', '不同高度的姿态'], ['Standing and kneeling make dependence visible. Modern reflection can ask how generosity might preserve dignity as well as transfer resources.', '站立与跪姿使依赖可见。现代反思可以问，慷慨怎样在转移资源的同时保留尊严。']],
    ],
    reflection: ['This card can invite a review of how giving and receiving feel in practice. Is help offered with clear expectations? Can the recipient say what would actually be useful? Does the exchange create obligation that nobody has named? These are contemporary extensions of the scene rather than predictions about a benefactor. Waite’s positive account remains part of its history, while Smith’s visible arrangement gives room to examine the quality of generosity instead of assuming that every gift works equally well.', '这张牌可以邀请我们检视实际施受的感受。帮助是否带着清楚的期待？接受者能说出真正有用的是什么吗？交换是否产生没人说明的义务？这些是场景的现代延伸，而不是对某位恩人的预言。韦特的正面解释仍属于历史；史密斯的构图则让我们能检视慷慨的质量，而不假设每份礼物都同样有益。'],
    detail: ['The large pentacles above are not the tiny coins falling from the hand. Smith preserves the card’s count while showing an ordinary act of distribution.', '上方大星币并不是手中落下的小钱。史密斯既保留牌的点数，又画出了普通的分配动作。'],
  },
  {
    id: 'pentacles-07',
    teaser: ['A gardener stops working to look: the pause may matter as much as the crop.', '园丁停下劳动开始看：这次暂停可能与收成同样重要。'],
    past: ['Waite is unusually candid about contradictory interpretations here. He describes a person gazing at treasured pentacles in greenery, but his list includes business and barter alongside meanings that do not fit neatly together. The now familiar emphasis on patience and long-term investment is therefore a later selection from the image’s possibilities, not an uncontested ancient definition. The historical text preserves uncertainty, while the picture offers a much clearer situation: effort has produced something worth examining.', '韦特在这里很坦率地承认解释相互矛盾。他描写人物凝视绿叶中的珍贵星币，但词表既包括商业、交换，也包括难以协调的其他意义。因此，今天常见的耐心与长期投入，是从图像可能性中选出的一条方向，而不是没有争议的古老定义。文字保留了不确定，画面却给出较清楚的处境：努力已经产生值得检视的东西。'],
    scene: ['Smith’s figure leans on a long-handled tool, turning toward a growth that carries the suit’s round emblems. One disc sits lower, near the feet, while the others cluster in the foliage. The body is resting but the gaze is active. There is no visible harvest basket, sale, or completed transaction. The scene occupies an interval between labour and a conclusion, which helps explain why later readers find assessment and waiting more compelling than an instant result.', '史密斯的人物倚着长柄工具，望向长有圆形花色标志的植物。一枚圆盘较低，靠近脚边，其余聚在叶丛中。身体休息，目光却仍在工作。画面没有收成篮、出售或完成的交易。它处在劳动与结论之间的间隔，这也解释了为何后世读者更容易想到评估与等待，而非即时结果。'],
    symbols: [
      [['Resting on a tool', '倚着工具'], ['The tool links the pause to preceding work. This is not simply idleness; the body carries a relationship to effort even while it is still.', '工具把暂停与之前的劳动连接起来。这并非单纯懒散；即使静止，身体仍显示与努力的关系。']],
      [['Pentacles in foliage', '叶丛中的星币'], ['Value appears to have grown rather than arrived fully formed. That visual metaphor supports cultivation, though it does not guarantee a future profit.', '价值像是生长出来，而非完整降临。这种比喻支持培育，却不保证未来利润。']],
      [['Attentive gaze', '专注目光'], ['The figure looks rather than reaches. The distinction makes evaluation and noticing central to the moment.', '人物在看，而不是伸手拿取。这个区别让评估与观察成为这一刻的核心。']],
    ],
    reflection: ['A present-day reading can ask whether continued effort is producing what matters, and whether the method needs adjustment. Patience is not the same as persisting forever without reviewing the evidence. The pause can hold pride, fatigue, disappointment, or a mixture of all three; the face does not settle the question for us. Waite’s acknowledgement of disagreement encourages that openness. Looking carefully at what has actually developed is more useful than deciding in advance that waiting must be rewarded.', '现代阅读可以问：持续努力是否在产出重要之物，方法是否需要调整？耐心不等于永远坚持而不审视证据。这次暂停可以包含自豪、疲惫、失望，或三者混合；面孔没有替我们作出唯一判定。韦特承认分歧，也鼓励这种开放。仔细观察实际长出了什么，比预先认定等待必然获得回报更有用。'],
    detail: ['Waite calls the meanings contradictory. The familiar “patience will pay” message is an interpretation of the garden, not a promise established by the original text.', '韦特称这些含义相互矛盾。熟悉的“耐心必有回报”是对花园的解释，并非原文确立的承诺。'],
  },
  {
    id: 'pentacles-08',
    teaser: ['One person makes the same object again and again, turning the coin suit into a portrait of learning by hand.', '一个人反复制作同类物件，把钱币花色变成用双手学习的肖像。'],
    past: ['Waite describes an artisan working in stone and connects the card with employment, commissions, and craft, possibly at a preparatory stage. Elsewhere he compares this worker with the more established sculptor in the Three of Pentacles. That comparison gives the card a professional history within the deck: skill develops through practice before it is fully recognized. The older count of eight objects becomes a visible series of attempts or products rather than merely an amount of money.', '韦特把人物描述为石作工匠，把牌与就业、委托和技艺相连，也可能处在准备阶段。他又在别处把这个人和星币三更成熟的雕刻师相比。这使牌在整副牌中拥有职业发展的关系：技巧通过练习成长，随后才充分得到认可。旧有的八个物件计数，变成可见的练习或产品序列，而不只是金钱数额。'],
    scene: ['Smith seats the worker at a bench, focused on a pentacle being shaped. Finished discs are displayed in a vertical line nearby, with another at the feet. A settlement sits far in the background, leaving the foreground absorbed in the small task. Repetition is visible, but so is attention to the current object. The scene does not show a crowd applauding or a customer paying. Its drama lies in making rather than in the moment of reward.', '史密斯让工匠坐在工作台前，专注于正在成形的星币。完成的圆盘在旁边竖排展示，脚边还有一枚。聚落位于远景，使前景沉浸在眼前小任务中。重复清楚可见，对当前物件的关注也同样明显。画面没有鼓掌群众或付款客户，戏剧性存在于制作，而非回报时刻。'],
    symbols: [
      [['Tool and working hand', '工具与工作中的手'], ['The visible action connects effort with a specific technique. It is an image of doing and improving, not simply possessing talent in the abstract.', '可见动作把努力与具体技术连接起来。这是实践与改进的图像，而不只是抽象地拥有天分。']],
      [['Displayed discs', '陈列的圆盘'], ['The line of completed objects makes repetition legible. Each finished piece also provides something against which the next effort can be compared.', '完成品的排列使重复一目了然，每一件也提供了与下一次尝试比较的依据。']],
      [['Distant settlement', '远处聚落'], ['The town remains present but does not occupy the worker’s immediate attention. This supports a reading of concentration without proving permanent social withdrawal.', '城镇仍在，却没有占据工匠当下的注意。它支持专注的理解，但不能证明永久退离社会。']],
    ],
    reflection: ['The card can help turn an ambitious wish into a practice small enough to repeat. What part of the work can be observed, tried, and improved? It also raises a limit: repetition alone does not guarantee learning if no feedback is noticed. Waite’s contrast with the Three suggests that solitary preparation and recognized contribution are different conditions. A thoughtful modern reading values both, without making a person’s worth depend on constant output or endless self-improvement.', '这张牌可以帮助把宏大愿望转为足够小、能够重复的练习。工作中哪一部分可以观察、尝试、改进？它也提示限制：如果不注意反馈，重复本身并不保证学习。韦特与星币三的对照说明，独自准备和被认可的贡献是不同状态。周到的现代阅读可以珍惜两者，却不把个人价值建立在不断产出或无尽自我改进上。'],
    detail: ['Waite calls this worker an artisan in stone. The common modern image of a metal coin-maker is understandable, but it is not his exact description.', '韦特称工匠从事石作。现代把他想成金属钱币制造者虽可理解，却不是原文的准确描述。'],
  },
  {
    id: 'pentacles-09',
    teaser: ['A garden, a bird, and a solitary figure make abundance feel cultivated rather than hurried.', '花园、鸟与独处的人，让富足显得经过培育，而非匆忙得到。'],
    past: ['Waite associates the card with prudence, safety, success, and discernment. He suggests that the garden may belong to the woman, but presents that ownership as a possibility. Modern readings often make self-earned independence central; that is a plausible development, not a detail conclusively established by the historical description. The distinction matters because the picture shows comfort clearly, while the precise route by which that comfort was obtained remains outside the frame.', '韦特把牌与谨慎、安全、成功和辨别相连。他推测花园可能属于女子，但把所有权当成一种可能。现代阅读常强调自己挣来的独立，这可以是合理发展，却不是旧描述已经确证的细节。区别在于，画面清楚表现舒适，至于舒适通过何种途径获得，则留在画外。'],
    scene: ['Smith places the figure among heavy vines, dressed in a patterned robe and holding a bird on a gloved hand. Pentacles appear within the garden’s abundance. The setting feels enclosed and tended, unlike the exposed snow of the Five. Yet the figure is alone, giving the scene a quiet rather than communal satisfaction. The bird introduces a living relationship that requires attention; the abundance is not simply an inert pile of objects waiting to be counted.', '史密斯让人物站在茂盛藤蔓间，穿着有纹样的长袍，戴手套的手托着一只鸟。星币融入花园的丰饶。环境受到围护与照料，不同于星币五暴露在雪中的场景。人物却是独处，使满足显得安静而非集体欢庆。鸟引入需要注意的生命关系；富足并非一堆等着被数清的死物。'],
    symbols: [
      [['Vines', '葡萄藤'], ['The cultivated plants make care and favorable conditions visible. They allow abundance to feel organic and maintained, rather than merely acquired once.', '经过培育的植物让照料与良好条件可见，使富足显得有生命、需要维持，而非获得一次就结束。']],
      [['Gloved hand and bird', '手套与鸟'], ['The bird is held with a protective glove. Later readers may connect it with trained attention or refinement; the image alone does not supply one fixed code.', '鸟停在戴防护手套的手上。后世可以联想到受训练的注意或雅致，但图像没有提供固定唯一的密码。']],
      [['Solitary figure', '独处人物'], ['The absence of a group distinguishes this pleasure from the Ten’s family scene. Solitude here can be spacious rather than automatically lonely.', '没有群体，使这种快乐区别于星币十的家族场面。这里的独处可以宽裕，并非自动等于孤独。']],
    ],
    reflection: ['The card can invite appreciation of what has become stable enough to enjoy. That might include a skill, a private routine, a safe space, or a measure of independence. It can also ask what care makes that comfort possible, including contributions that are easy to overlook. Reading the image as cultivated wellbeing is different from assuming that every comfortable person earned everything alone. Waite’s cautious wording about ownership leaves room for a less simplistic account of prosperity.', '这张牌可以邀请人欣赏已经稳定到足以享受的东西：技能、私人习惯、安全空间，或某种独立。也可以追问什么照料使舒适成为可能，包括容易被忽视的贡献。把图像理解为经过培育的安适，不等于假设每个舒适的人都独自挣来一切。韦特对所有权的谨慎措辞，也为更不简单化的富足叙事留下空间。'],
    detail: ['The handbook says the estate may be hers. That small uncertainty is worth preserving when discussing the card’s later association with financial independence.', '说明书只说庄园可能属于她。讨论后世的财务独立联想时，值得保留这点小小的不确定。'],
  },
  {
    id: 'pentacles-10',
    teaser: ['The coins overlay a household of different generations: wealth becomes a story about what outlasts one person.', '钱币覆盖在多代同堂的场景上：财富变成关于什么能超越个人生命的故事。'],
    past: ['Waite links the Ten with riches, family affairs, ancestry, records, and a family dwelling. Those associations shift the coin suit from an individual object toward continuity across people and time. The card is not a documented portrait of one named historical household. Rather, its domestic imagery makes inheritance and belonging available as themes. The history of interpretation here concerns how material resources become part of a family narrative, including what is kept, remembered, and passed on.', '韦特把星币十与财富、家事、祖先、档案及家族住所相连。这些联想使钱币花色从个人物品转向跨越人物与时间的延续。这张牌并非有据可查的某个历史家族肖像，而是通过家庭图像使继承与归属成为主题。它的解释史关乎物质资源如何进入家族叙事，包括什么被保留、被记住和被传递。'],
    scene: ['Smith places an older person near the foreground, with dogs, a child, and adults gathered around an architectural entrance. The figures do not all look in the same direction, which gives the scene the layered quality of everyday household life. Ten pentacles are superimposed across the picture rather than held by a single owner. The arch frames people and surroundings together. Unlike the Nine’s private garden, this setting makes continuity communal and visually crowded.', '史密斯把老人放在前景附近，狗、孩子与成年人围绕建筑入口出现。人物并没有全部朝同一方向看，这让场景具有日常家庭生活的层次。十枚星币覆盖在整个画面上，而不是由一个主人握住。拱门把人物与环境框在一起。与星币九的私人花园相比，这里的延续具有共同体性质，视觉上也更丰富拥挤。'],
    symbols: [
      [['Several generations', '不同世代'], ['The older person, adults, and child make time visible within one frame. The scene can concern continuity without defining one compulsory form of family.', '老人、成年人和孩子把时间呈现在同一画框中。场景可以关乎延续，却不规定唯一必须遵循的家庭形式。']],
      [['Archway', '拱门'], ['The entrance links household and wider world. It suggests a place that can be inhabited and inherited, not just a sum stored elsewhere.', '入口连接家庭与更广阔世界，提示可居住、可传承的地方，而不只是存放在别处的金额。']],
      [['Coins across the scene', '覆盖场景的钱币'], ['The pentacles organize the whole composition. Their dispersed placement makes value appear woven into relationships and surroundings rather than one isolated possession.', '星币组织整个构图。分散的位置让价值融入关系与环境，而不是成为孤立财物。']],
    ],
    reflection: ['A modern reading can ask what kind of legacy is being created through repeated choices. Money may be one part, but so may knowledge, habits, care, or a sense of welcome. It can also ask who belongs inside the picture and who might be excluded by its idea of continuity. These questions extend the household imagery without assuming that tradition is always comforting. Waite’s mention of records is a useful reminder that inheritance includes stories and documents as well as valuables.', '现代阅读可以问，重复的选择正在创造怎样的传承。金钱可能是其中一部分，知识、习惯、照料或欢迎感也同样如此。还可以问，谁属于画面内部，谁可能被某种延续观排除。这些问题扩展了家庭图像，却不假设传统总是令人安慰。韦特提到档案，也提醒我们继承包含故事与文书，不只有贵重物。'],
    detail: ['Waite includes archives among the meanings. The Ten’s legacy can be remembered and recorded, not only owned.', '韦特把档案列入含义。因此，星币十的传承可以被记忆和记录，而不仅是被拥有。'],
  },
  {
    id: 'pentacles-11',
    teaser: ['A young figure studies one pentacle so closely that the world seems to pause around it.', '年轻人物如此专注地研究一枚星币，仿佛周围世界都暂停了。'],
    past: ['The Page retains the junior court rank, but Waite’s emphasis is not chiefly on service at a royal household. He describes a studious figure absorbed in the pentacle and connects the card with application, scholarship, reflection, and messages. The old court role has become a portrait of attention. Modern interpretations of new practical skills fit this emphasis, although the handbook does not limit the subject to a particular course of study or a promised career opportunity.', '侍从保留较低宫廷等级，但韦特的重点并非主要在王室服务。他描述人物沉浸于星币，并把牌与用功、学问、反思及消息相连。旧宫廷角色转为注意力的肖像。现代关于新实用技能的解释与此相合，但说明书没有限定某个学习专业，也没有保证职业机会。'],
    scene: ['Smith sets the Page in an open landscape, holding the pentacle before the face with both hands. The gaze rises to the object, and the body looks measured rather than hurried. Fields and distant heights suggest a world of possible work beyond the immediate act of looking. Unlike the Knight, this figure is not yet mounted for a task. The scene emphasizes beginning to understand the emblem before confidently putting it into service.', '史密斯把侍从放在开阔景色中，双手将星币举到面前。目光朝向物件，身体显得有分寸而不匆忙。田野与远处高地提示，眼前观察之外还存在许多可能的工作。与骑士不同，这个人尚未骑马承担任务。场景强调先理解标志，再有把握地把它用于实践。'],
    symbols: [
      [['Lifted pentacle', '举起的星币'], ['The object is displayed as a subject of study. Its value lies in sustained attention as much as immediate possession.', '物件被举起成为研究对象。它的价值不仅在于立即拥有，也在于持续关注。']],
      [['Two supporting hands', '承托的双手'], ['The careful hold makes concentration bodily. It can suggest a learner giving a new skill enough space and steadiness to develop.', '仔细托举使专注成为身体动作，可以提示学习者给新技能足够空间与稳定。']],
      [['Open ground', '开阔土地'], ['The spacious setting leaves room for future application. It supports possibility without identifying a specific job, payment, or result.', '宽阔环境为未来应用留下空间，支持可能性，却不指定某份工作、报酬或结果。']],
    ],
    reflection: ['The card can encourage a beginner’s willingness to look carefully at something ordinary. Understanding a tool, keeping a small practice, or asking an exact question may be more useful than announcing a grand ambition. Court roles can describe an approach rather than a fixed person: anyone can be the Page when learning patiently. The historical emphasis on study also complicates the idea that this suit is only about money. Here material symbolism becomes a focus for knowledge and sustained interest.', '这张牌可以鼓励初学者仔细观察普通事物。理解工具、维持小练习或提出准确问题，可能比宣告宏大抱负更有效。宫廷角色可以描写做事方式，而不是固定人物；任何人耐心学习时，都可能处在侍从的位置。旧文本对学问的强调，也使“这个花色只关乎钱”显得不够。在这里，物质符号成为知识与持续兴趣的焦点。'],
    detail: ['Waite explicitly includes scholarship. The studious Page shows that even the original Pentacles descriptions range beyond income and possessions.', '韦特明确提到学问。好学的侍从表明，即使原有星币描述，也超出了收入与财物。'],
  },
  {
    id: 'pentacles-12',
    teaser: ['The stillest mounted figure in the deck makes endurance, rather than speed, the centre of the journey.', '牌组中最安静的骑乘者，让耐力而非速度成为旅程中心。'],
    past: ['Waite describes a slow, enduring horse whose temperament corresponds with its rider. He associates this Knight with usefulness, service, responsibility, and upright conduct. Unlike the charging Sword Knight, this court member is defined by dependable capacity rather than immediate conquest. The inherited knightly rank has been adapted into a practical role. Its history is a small lesson in how one court title can support very different forms of action when placed within different suits.', '韦特描述一匹缓慢、耐久的马，性情与骑手相应。他把骑士与实用、服务、责任和正直行为相连。不同于冲锋的宝剑骑士，这位宫廷成员以可靠能力而非立即征服为特征。继承来的骑士等级，被调整为实际角色。它展示同一宫廷称号在不同花色中，如何支持截然不同的行动方式。'],
    scene: ['Smith’s horse appears almost stationary, with the rider holding the pentacle before him. A worked field stretches behind, grounding the scene in labour rather than spectacle. Armour remains part of the knightly costume, but no enemy demands an attack. The stillness can look uneventful until compared with the other mounted cards. Then it becomes deliberate: the picture makes readiness and persistence visible without needing the dramatic gesture of a charge.', '史密斯的马几乎静止，骑手把星币举在身前。身后的耕地让场景扎根于劳动，而不是壮观表演。盔甲仍属于骑士服装，却没有敌人要求攻击。若不与其他骑乘牌对比，这种安静可能显得无事发生；比较之后，它就显出有意识的选择：无需冲锋的戏剧动作，画面也能表现准备与坚持。'],
    symbols: [
      [['Heavy horse', '厚重的马'], ['The horse emphasizes carrying power and endurance. Its still posture makes capacity feel different from speed.', '马强调负载能力与耐力，静止姿态使能力与速度成为不同概念。']],
      [['Presented pentacle', '展示的星币'], ['The rider holds the emblem outward. Waite distinguishes this display from the Page’s absorbed study, suggesting a different relationship to the same object.', '骑手把标志朝外举着。韦特区分这种展示与侍从沉浸的研究，说明对同一物件也能有不同关系。']],
      [['Worked field', '耕作过的田地'], ['The landscape suggests preparation and repeated effort. It places the knightly figure within an ordinary material world rather than an exceptional battle.', '景色提示准备与反复劳动，把骑士放在普通物质世界里，而非非凡战役中。']],
    ],
    reflection: ['The card can help distinguish steadiness from stagnation. A routine is valuable when it keeps an important promise, but may need revision when it no longer serves the work. What is the next reliable action, and what evidence would show that the method needs to change? These modern questions preserve the historical emphasis on responsibility without turning patience into a demand to endure everything. The Knight’s useful strength is the ability to carry something through with care.', '这张牌可以帮助分辨稳定与停滞。习惯若能维持重要承诺，就有价值；若已不再服务工作，也可能需要修订。下一项可靠行动是什么，什么证据会说明方法需要改变？这些现代问题保留了旧解释对责任的重视，却不把耐心变成承受一切的要求。骑士有用的力量，是认真把一件事做下去的能力。'],
    detail: ['Waite says the Knight displays the pentacle rather than studies it. A small change of attention separates this role from the Page.', '韦特说骑士展示星币，而不是研究它。注意力的小变化，区分了骑士与侍从的角色。'],
  },
  {
    id: 'pentacles-13',
    teaser: ['The Queen looks down at a pentacle in a living garden, joining material comfort with attentive care.', '王后在有生命的花园里低头看星币，把物质舒适与专心照料连接起来。'],
    past: ['Waite describes this Queen through generosity, security, freedom, and seriousness of intelligence. Those terms make her more than a decorative emblem of wealth. As with other court figures, later readings have shifted away from trying to identify a person by physical appearance or fixed social position. Her role can instead describe a way of caring for resources. That is a modern application, while the older text already provides a clear basis for combining prosperity with thoughtful generosity.', '韦特以慷慨、安全、自由以及严肃的智慧描述这位王后，使她不只是财富装饰。像其他宫廷人物一样，后世阅读逐渐不再通过外貌或固定社会位置来指认某个人，而可以把角色理解为照料资源的方式。这是现代应用；旧文本也已经为富足与经过思考的慷慨相结合提供依据。'],
    scene: ['Smith seats the Queen beneath flowering growth, holding the pentacle in her lap and looking toward it. Plants, carved forms, and a small animal fill the surroundings, making the throne part of a living environment rather than an isolated platform. The figure’s attention is inward and downward, but not withdrawn from material life. Compared with the King’s frontal display, this posture makes wealth feel held, considered, and placed within a field of care.', '史密斯让王后坐在开花植物下，星币放在膝上，目光朝向它。植物、雕刻形态与小动物填满环境，使宝座成为有生命环境的一部分，而非孤立高台。人物的注意向内、向下，却没有脱离物质生活。与国王较正面的展示相比，这个姿态使财富显得被托住、被思考，并处在照料之中。'],
    symbols: [
      [['Pentacle in the lap', '膝上的星币'], ['The supported disc makes possession look attentive rather than defensive. Its placement invites a reading of stewardship, though that is an interpretive term.', '被托住的圆盘让占有显得专心，而非防御。位置可以引出照管的理解，但“照管”仍是解释性用语。']],
      [['Flowering surroundings', '开花的环境'], ['The garden surrounds authority with growth. Comfort appears connected to a maintained environment rather than separated from ordinary living conditions.', '花园以生长环绕权威。舒适显得与被维持的环境相连，而非脱离普通生活条件。']],
      [['Small rabbit', '小兔子'], ['The animal is an easily missed living detail near the foreground. It broadens the scene beyond human status without requiring a single coded explanation.', '前景附近的小动物容易被忽略。它把场景扩展到人的地位之外，却不必有唯一的密码式解释。']],
    ],
    reflection: ['The card can ask how practical care makes a space, project, or relationship easier to live in. Warmth often depends on small material acts: maintaining something, sharing a resource, or noticing an unmet need. That does not mean one person should become responsible for everyone else’s comfort. A contemporary reading can include the caregiver’s own freedom and security, both already present in Waite’s vocabulary. Sustainable generosity needs a place for the giver as well as the receiver.', '这张牌可以问，实际照料怎样让空间、项目或关系更容易安住。温暖常依赖小小的物质行动：维护东西、分享资源，或注意未被满足的需要。这并不表示一个人应为所有人的舒适负责。现代阅读也可以包含照料者自己的自由与安全，而这两个词原本就在韦特的词汇中。能够持续的慷慨，需要同时给施予者与接受者留位置。'],
    detail: ['Waite includes liberty as well as generosity. The Queen’s historical description leaves room for personal freedom, not only duty to other people.', '韦特既写慷慨，也写自由。因此王后的历史描述为个人自主留下空间，而不仅是对他人的义务。'],
  },
  {
    id: 'pentacles-14',
    teaser: ['Vines and carved bulls surround a ruler whose real subject is turning ability into something dependable.', '藤蔓与雕刻公牛围绕统治者，他真正的主题是把能力变成可靠成果。'],
    past: ['This is where Waite pauses to explain the suit’s change from ordinary coins to pentacles marked with a five-pointed star. He states that the substitution was not his invention and that the suit is not exclusively concerned with money. His King’s meanings include business aptitude, practical intelligence, and success in applying those capacities. The historical emphasis is therefore broader than being rich: it concerns the ability to make understanding work effectively in the material world.', '韦特在这张牌处停下来，解释花色如何从普通钱币转为带五角星的星币。他说明这种替换并非他的发明，而且花色并不专门处理金钱问题。国王的含义包括商业能力、实际智慧，以及运用这些能力取得成功。因此，旧解释比“有钱”更宽广，关乎让理解在物质世界有效发挥作用的能力。'],
    scene: ['Smith gives the King an elaborate throne and a robe patterned with vines. Bulls appear in the carving, and growing plants blur the boundary between clothing, seat, and garden. The pentacle rests prominently before him, while the surrounding architecture implies an established domain. There is little suggestion of hurried acquisition. Instead, the composition gathers signs of abundance around a settled figure, making the question one of maintaining and using what has already been built.', '史密斯赋予国王华丽宝座与藤蔓纹长袍。公牛出现在雕刻中，生长植物模糊了衣物、座位和花园的界线。星币醒目地置于身前，周围建筑暗示已经建立的领域。画面几乎没有匆忙攫取的感觉，而是把富足迹象聚在安定人物周围，使问题转为如何维持和使用已经建成的东西。'],
    symbols: [
      [['Carved bulls', '雕刻公牛'], ['Waite specifically draws attention to the repeated bull heads. Later astrological readings may connect them with Taurus, but the handbook does not explain every detail of that association here.', '韦特特别提醒留意反复出现的牛头。后世占星阅读可能把它们与金牛座相连，但此处说明书没有详解全部对应。']],
      [['Vine-patterned robe', '藤蔓纹长袍'], ['The pattern joins the ruler visually to the growing surroundings. It makes abundance feel enveloping rather than confined to the single disc.', '纹样在视觉上把统治者与生长环境相连，使丰饶环绕全身，而不局限于一枚圆盘。']],
      [['Established seat', '稳固的座位'], ['The heavy throne suggests continuity and settled authority. A modern reading can ask how such security is maintained and whom it supports.', '厚重宝座提示延续与稳定权威。现代阅读可以追问，这种安全如何被维持，又支持谁。']],
    ],
    reflection: ['The King can offer a practical standard for competence: does an idea become something that works reliably for people over time? That may involve planning, maintenance, fair use of resources, or sharing expertise. The image also invites scrutiny of comfort that has become complacency. Stability is valuable, but it is not a reason to stop learning. Waite’s broad account of intelligence helps keep the role open to anyone who develops sound judgment, rather than reserving it for wealth or status.', '国王可以提出实际的能力标准：想法能否变成长期可靠、对人有用的东西？这可能涉及规划、维护、公平使用资源，或分享专业知识。图像也邀请我们审视舒适是否变成自满。稳定很宝贵，却不是停止学习的理由。韦特对智慧的广泛理解，让任何培养良好判断的人都能进入这个角色，而不只属于富人或有地位者。'],
    detail: ['The explanation of why coins became pentacles appears in this King’s entry. Waite himself says the suit reaches beyond money.', '关于钱币为何变成星币的解释，就写在这位国王的条目中。韦特本人明确说，花色的范围超过金钱。'],
  },
];

function story(entry: Entry, language: 0 | 1): Story {
  const suit = entry.id.split('-')[0];
  return {
    teaser: entry.teaser[language],
    origin: [historical[suit][language], entry.past[language]],
    evolution: [entry.scene[language], comparisons[entry.id][language]],
    symbols: entry.symbols.map(([name, text]) => ({ name: name[language], text: text[language] })),
    today: [entry.reflection[language]],
    detail: entry.detail[language],
    sources: ['https://www.metmuseum.org/perspectives/tarot-2', 'https://en.wikisource.org/wiki/The_Pictorial_Key_to_the_Tarot/Part_3'],
  };
}
export const historySwordsPentacles: Record<string, { en: Story; 'zh-CN': Story }> = Object.fromEntries(entries.map(entry => [entry.id, { en: story(entry, 0), 'zh-CN': story(entry, 1) }]));
